window.HMC_INFO = {"28790061":{"noi_dau":["Ngủ đủ giấc mà sáng dậy người vẫn uể oải, thiếu sức","Ăn chay hoặc ăn ít thịt nên lo cơ thể thiếu vitamin B12","Tuổi càng lớn càng hay mệt, làm việc nhanh đuối"],"cong_dung":["Bổ sung vitamin B12 hàm lượng 1000 mcg mỗi viên","Hỗ trợ giảm mệt mỏi ở người thiếu vitamin B12 theo công bố trên nhãn","Hỗ trợ chức năng tế bào não","Góp phần chuyển hóa năng lượng từ thức ăn"],"thanh_phan_chinh":"Vitamin B12 1000 mcg/viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày với nước, cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú hoặc người đang dùng thuốc nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"36404119":{"noi_dau":["Vùng kín hay khó chịu, mỗi lần thay đổi thời tiết lại lo","Bụng hay đầy hơi, đi ngoài thất thường","Muốn chăm sóc sức khoẻ phụ nữ từ bên trong mà ngại thuốc"],"cong_dung":["Bổ sung 25 tỷ lợi khuẩn sống từ 10 chủng men vi sinh","Hỗ trợ sức khoẻ vùng kín của phụ nữ","Hỗ trợ hệ tiêu hoá khoẻ mạnh","Góp phần hỗ trợ hệ miễn dịch"],"thanh_phan_chinh":"25 tỷ lợi khuẩn sống (CFU), 10 chủng men vi sinh/viên","lieu_dung":"Uống 1 viên mỗi ngày.","luu_y":["Phụ nữ có thai, cho con bú, người có bệnh lý hoặc suy giảm miễn dịch nên hỏi bác sĩ trước khi dùng."]},"42562981":{"noi_dau":["Đứng bán hàng cả ngày, tối về vai gáy mỏi nhừ","Đau lưng, đau khớp gối mỗi lần trở trời","Tập thể dục xong cơ bắp căng cứng, đau nhức"],"cong_dung":["Giảm tạm thời đau nhẹ ở cơ và khớp","Dùng khi đau lưng đơn thuần, viêm khớp, căng cơ, bầm, bong gân","Cảm giác mát lạnh nhanh, dạng lăn không dính tay"],"thanh_phan_chinh":"Menthol 4%","lieu_dung":"Người lớn và trẻ từ 12 tuổi: lăn lên vùng đau, không quá 4 lần mỗi ngày. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Chỉ dùng ngoài da; dễ cháy, tránh xa lửa; tránh tiếp xúc mắt và niêm mạc.","Ngưng dùng và hỏi bác sĩ nếu đau, sưng, phồng rộp hoặc triệu chứng kéo dài quá 7 ngày."]},"97977162":{"noi_dau":["Sáng vội đi làm, áo nhăn mà không kịp bật bàn là","Quần áo mặc một lần còn sạch nhưng ám mùi đồ ăn, khói","Váy áo chất liệu mỏng hay bị tĩnh điện, dính vào người"],"cong_dung":["Giúp giảm nếp nhăn trên quần áo mà không cần là","Khử mùi và tạo hương thơm tươi mát cho vải","Giảm tĩnh điện trên quần áo","Bình xịt nhỏ gọn, mang theo khi đi công tác, du lịch"],"lieu_dung":"Lắc đều, xịt cách quần áo khoảng 15–20 cm cho vải hơi ẩm, kéo phẳng và vuốt nhẹ nếp nhăn rồi để khô.","luu_y":["Bình chứa khí nén: không chọc thủng, không đốt, không để nơi nhiệt độ cao.","Để xa tầm tay trẻ em, không xịt vào mặt và mắt."]},"wn-ginkgo-120":{"noi_dau":["Vừa cầm chìa khoá trên tay mà quay đi đã quên để ở đâu.","Đọc vài trang sách là đầu óc mỏi, khó tập trung như trước.","Tay chân hay lạnh, tê bì mỗi sáng thức dậy làm mình lo lắng."],"cong_dung":["Hỗ trợ tăng cường chức năng nhận thức và trí nhớ ở người lớn.","Góp phần hỗ trợ tuần hoàn ngoại biên, giúp máu lưu thông tới tay chân.","Chiết xuất lá bạch quả chuẩn hoá 24% flavone glycoside và 6% terpene lactone."],"thanh_phan_chinh":"Chiết xuất lá bạch quả 50:1 120 mg/viên (tương đương 6.000 mg lá khô)","lieu_dung":"Người lớn uống 1 viên x 2 lần/ngày hoặc theo chỉ dẫn của bác sĩ. Hỏi ý kiến bác sĩ nếu dùng quá 4 tuần.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc tiểu đường, huyết áp hoặc chống động kinh cần hỏi bác sĩ trước khi dùng.","Không dùng chung với thuốc chống đông, aspirin, ibuprofen, dầu cá hoặc vitamin E vì tăng nguy cơ chảy máu.","Để xa tầm tay trẻ em."]},"wn-omega3-900":{"noi_dau":["Bước sang tuổi bốn mươi, chỉ số mỡ máu trong lần khám gần nhất bắt đầu nhích lên.","Làm việc nhiều, đầu óc dễ mệt và hay quên việc nhỏ trong ngày.","Muốn bổ sung dầu cá mà ngại uống nhiều viên, ợ lên mùi tanh."],"cong_dung":["Hỗ trợ sức khoẻ tim mạch và chức năng não bộ.","Góp phần giảm triglyceride trong máu khi dùng theo liều trên nhãn.","Hỗ trợ cân bằng tâm trạng và quá trình kháng viêm lành mạnh của cơ thể.","Viên bao tan trong ruột, giảm vị tanh dầu cá sau khi uống."],"thanh_phan_chinh":"Omega-3 900 mg/viên (EPA 600 mg, DHA 300 mg) từ 1.425 mg dầu cá cô đặc","lieu_dung":"Người lớn uống 1 viên/ngày để bổ sung omega-3; 2 viên/ngày khi cần hỗ trợ giảm triglyceride hoặc cân bằng tâm trạng, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người dị ứng cá cần đọc kỹ nhãn trước khi dùng.","Để xa tầm tay trẻ em, bảo quản tránh nóng và ẩm."]},"ks-multi-gummy":{"noi_dau":["Bận rộn cả ngày, bữa ăn thất thường nên lo thiếu vitamin mà không biết.","Ngại nuốt viên thuốc to, mua vitamin về rồi để quên trong tủ.","Hay mệt mỏi, dễ ốm vặt mỗi khi thời tiết thay đổi."],"cong_dung":["Bổ sung vitamin và khoáng chất, góp phần duy trì sức khoẻ tốt.","Hỗ trợ chức năng hệ miễn dịch.","Dạng kẹo dẻo làm từ pectin, vị anh đào, cam và quả mọng dễ ăn.","Không chứa sữa, gluten, các loại hạt và gelatin."],"thanh_phan_chinh":"Mỗi viên: vitamin A 306 mcg RAE, vitamin C 20 mg, vitamin D 6,25 mcg, folate 140 mcg, B12 2,15 mcg, kẽm 2,5 mg cùng nhiều vi chất khác","lieu_dung":"Người lớn nhai 2–4 viên, 1 lần/ngày cùng bữa ăn; uống cách các thuốc hoặc sản phẩm sức khoẻ khác vài giờ.","luu_y":["Để xa tầm tay trẻ em; không dùng nếu niêm phong dưới nắp bị rách hoặc mất.","Màu kẹo có thể sẫm dần theo thời gian, không ảnh hưởng chất lượng."]},"yt-collagen-390":{"noi_dau":["Soi gương thấy da kém căng, nếp nhăn khoé mắt rõ hơn năm ngoái.","Tóc rụng nhiều, móng tay mỏng và dễ gãy.","Lên xuống cầu thang đầu gối bắt đầu ê ẩm, cứng khớp buổi sáng."],"cong_dung":["Bổ sung collagen thuỷ phân, lượng collagen trong cơ thể giảm dần theo tuổi.","Cung cấp lysine, axit amin góp phần hình thành collagen.","Vitamin C hỗ trợ hình thành mô liên kết.","Hỗ trợ giảm đau khớp liên quan đến thoái hoá khớp."],"thanh_phan_chinh":"Collagen thuỷ phân 6.000 mg và vitamin C 60 mg mỗi khẩu phần 6 viên","lieu_dung":"Người lớn uống 6 viên/ngày, chia 3 viên x 2 lần hoặc uống một lần.","luu_y":["Không dùng cho phụ nữ có thai hoặc đang cho con bú; không dành cho người dưới 18 tuổi.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Sản xuất tại cơ sở có chế biến whey sữa và chiết xuất cá; có thể chứa dư lượng sulfite."]},"eagle-oil":{"noi_dau":["Ngồi máy tính cả ngày, tối về lưng mỏi, vai gáy cứng đơ.","Lỡ trẹo chân, va đập bầm tím mà nhà không có sẵn dầu xoa.","Bố mẹ lớn tuổi hay đau nhức khớp mỗi khi trời trở lạnh."],"cong_dung":["Giảm đau cơ và khớp do đau lưng, căng cơ.","Giảm đau do bầm tím và bong gân.","Mùi thơm the mát, chai nhỏ gọn tiện mang theo."],"thanh_phan_chinh":"Menthol 28,5%, methyl salicylate 18,6%, dầu khuynh diệp 1,56%","lieu_dung":"Người lớn và trẻ từ 13 tuổi trở lên: thoa lên vùng đau 3–4 lần/ngày khi cần.","luu_y":["Chỉ dùng ngoài da, tránh tiếp xúc với mắt; không thoa lên vết thương, da trầy xước, không băng kín hoặc chườm nóng.","Không dùng nếu dị ứng salicylate hoặc đang dùng thuốc chống đông máu.","Ngưng dùng và hỏi bác sĩ nếu triệu chứng nặng hơn, kéo dài quá 7 ngày hoặc nổi mẩn, kích ứng."]},"wn-k2-d3":{"noi_dau":["Bước sang tuổi trung niên, lo xương yếu dần mà không biết bắt đầu từ đâu.","Uống canxi đều đặn nhưng không rõ cơ thể có hấp thu được không.","Ít ra nắng, làm việc trong nhà nên lo thiếu vitamin D."],"cong_dung":["Hỗ trợ hấp thu canxi và phospho.","Góp phần xây dựng và duy trì xương, răng chắc khoẻ.","Hỗ trợ chức năng hệ miễn dịch.","Dùng vitamin K2 dạng MK-7 có hoạt tính sinh học."],"thanh_phan_chinh":"Vitamin K2 (MK-7) 120 mcg và vitamin D3 1.000 IU (25 mcg)/viên","lieu_dung":"Người lớn uống 1 viên/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người đang dùng thuốc chống đông máu cần hỏi ý kiến bác sĩ trước khi dùng.","Để xa tầm tay trẻ em; bảo quản tránh nóng, ánh sáng và độ ẩm."]},"glucerna":{"noi_dau":["Bố mẹ bị tiểu đường, bữa nào cũng phải cân nhắc ăn gì để đường huyết ổn.","Bữa sáng vội vàng, không có món nào vừa no vừa yên tâm cho người tiểu đường.","Người lớn tuổi ăn kém, lo thiếu chất nhưng ngại đồ uống nhiều đường."],"cong_dung":["Dinh dưỡng đầy đủ, cân đối dành cho người tiểu đường.","Dùng carbohydrate chỉ số đường huyết thấp, hỗ trợ hạn chế tăng đường huyết sau uống.","Mỗi chai cung cấp 11 g đạm, 5,6 g chất xơ và 26 vitamin, khoáng chất.","Có thể dùng thay một bữa ăn hoặc bữa phụ."],"thanh_phan_chinh":"Mỗi chai 237 ml: đạm 11 g, chất xơ 5,6 g, 26 vitamin và khoáng chất","lieu_dung":"Lắc đều trước khi uống, ngon hơn khi uống lạnh; dùng thay bữa ăn hoặc bữa phụ theo tư vấn của bác sĩ, chuyên gia dinh dưỡng. Sau khi mở nắp, đậy kín, bảo quản tủ lạnh và dùng trong 48 giờ.","luu_y":["Không dùng cho người bị bệnh galactosemia; không dùng đường tĩnh mạch.","Không dành cho trẻ em trừ khi có chỉ định của bác sĩ; người tiểu đường nên trao đổi với bác sĩ về chế độ ăn."]},"wn-super-sleep":{"noi_dau":["Nằm trằn trọc cả tiếng đồng hồ mà mắt vẫn mở thao láo.","Làm ca đêm, lệch múi giờ, nhịp ngủ đảo lộn mấy ngày chưa lại.","Đầu óc căng thẳng, khó thả lỏng để đi vào giấc ngủ."],"cong_dung":["Hỗ trợ rút ngắn thời gian đi vào giấc ngủ.","Góp phần điều chỉnh lại chu kỳ thức – ngủ.","Hỗ trợ tăng tổng thời gian ngủ khi làm ca hoặc lệch múi giờ.","Hỗ trợ thư giãn tạm thời nhờ L-theanine."],"thanh_phan_chinh":"Melatonin 2,5 mg, L-theanine 100 mg, 5-HTP 15 mg/viên nhai","lieu_dung":"Người lớn nhai 1–2 viên/ngày cùng thức ăn, vào hoặc trước giờ đi ngủ (để thư giãn: 2 viên). Hỏi ý kiến bác sĩ nếu dùng quá 4 tuần.","luu_y":["Không dùng cho phụ nữ có thai, đang cho con bú hoặc người bị xơ cứng bì.","Hỏi bác sĩ trước khi dùng nếu đang dùng thuốc chống trầm cảm, thuốc chống đông, thuốc huyết áp, thuốc an thần hoặc có bệnh tim, gan, thận, tiểu đường.","Không lái xe, vận hành máy móc trong 5 giờ sau khi dùng; tránh rượu bia."]},"ocuvite-50-150":{"noi_dau":["Ngoài năm mươi, nhìn chữ nhỏ phải đưa ra xa mới đọc được.","Dùng điện thoại, xem tivi lâu là mắt mỏi, khô và nhoè.","Lo đôi mắt kém dần theo tuổi mà không biết chăm sóc thế nào."],"cong_dung":["Hỗ trợ bảo vệ sức khoẻ mắt cho người từ 50 tuổi.","Lutein và zeaxanthin góp phần tăng cường sắc tố hoàng điểm, hỗ trợ lọc ánh sáng xanh.","Bổ sung omega-3, vitamin C, E, kẽm, đồng và vitamin D.","Viên mềm cỡ nhỏ, dễ uống, chỉ 1 viên mỗi ngày."],"thanh_phan_chinh":"Mỗi viên: vitamin C 150 mg, vitamin E 20 mg, kẽm 9 mg, đồng 1 mg, vitamin D 30 mcg cùng lutein, zeaxanthin và omega-3","lieu_dung":"Uống 1 viên/ngày vào buổi sáng, trong bữa ăn, với một cốc nước đầy.","luu_y":["Không dùng nếu niêm phong dưới nắp bị rách hoặc mất.","Để xa tầm tay trẻ em."]},"nb-zinc-50":{"noi_dau":["Cả nhà thay nhau cảm cúm, đứa này vừa khỏi đứa kia lại ốm.","Ăn uống thất thường, lo cơ thể thiếu vi chất mà không hay biết.","Da dễ nổi mụn, vết xước lâu lành hơn trước."],"cong_dung":["Hỗ trợ chức năng hệ miễn dịch.","Bổ sung kẽm, khoáng chất cần thiết cho nhiều hoạt động của cơ thể.","Kẽm gluconate hàm lượng cao, không biến đổi gen, không gluten, phù hợp người ăn chay."],"thanh_phan_chinh":"Kẽm (dạng zinc gluconate) 50 mg/viên","lieu_dung":"Người lớn uống 1 viên/ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Ngưng dùng và hỏi bác sĩ nếu có tác dụng phụ; để xa tầm tay trẻ em."]},"ks-vitc-chew":{"noi_dau":["Thời tiết giao mùa, cả nhà lại sụt sịt, hắt hơi liên tục.","Ngại nuốt viên to nên bỏ dở vitamin giữa chừng.","Ít ăn rau quả, lo thiếu vitamin C mà không để ý."],"cong_dung":["Hỗ trợ hệ miễn dịch.","Hỗ trợ hoạt động chống oxy hoá của cơ thể.","Viên nhai vị cam dễ dùng, đạt chứng nhận USP Verified."],"thanh_phan_chinh":"Vitamin C 500 mg/viên nhai","lieu_dung":"Người lớn nhai 1 viên/ngày, tốt nhất cùng bữa ăn.","luu_y":["Để xa tầm tay trẻ em.","Người đang mang thai, cho con bú hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng."]},"ntruth-acv-gummy":{"noi_dau":["Ăn uống điều độ mà cân nặng vẫn nhích lên từng chút.","Muốn thử giấm táo nhưng không uống nổi vị chua gắt.","Sau bữa ăn hay đầy bụng, khó tiêu, người nặng nề."],"cong_dung":["Bổ sung giấm táo hữu cơ ở dạng kẹo dẻo, không còn vị chua gắt.","Góp phần hỗ trợ tiêu hoá khi kết hợp chế độ ăn hợp lý.","Đạt chứng nhận hữu cơ USDA, thuần chay, không gluten, không biến đổi gen."],"thanh_phan_chinh":"Giấm táo hữu cơ 500 mg mỗi khẩu phần 2 viên kẹo","lieu_dung":"Người lớn dùng 2 viên kẹo/ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"ks-vite-500":{"noi_dau":["Da khô, kém mịn màng dù đã dùng đủ loại kem dưỡng.","Bước sang tuổi trung niên, lo cơ thể lão hoá nhanh hơn.","Hay mệt mỏi, dễ ốm, muốn bổ sung vi chất mà sợ uống sai."],"cong_dung":["Hỗ trợ hệ miễn dịch và hoạt động chống oxy hoá.","Vitamin E là dưỡng chất thiết yếu cho nhiều tế bào, trong đó có tế bào cơ tim.","Đạt chứng nhận USP Verified, lọ lớn dùng được lâu."],"thanh_phan_chinh":"Vitamin E (dl-alpha tocopheryl acetate) 180 mg (400 IU)/viên","lieu_dung":"Người lớn uống 1 viên/ngày, tốt nhất cùng bữa ăn.","luu_y":["Người đang mang thai, cho con bú, đang dùng thuốc (đặc biệt thuốc chống đông) nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"wn-k2-120":{"noi_dau":["Uống canxi mấy năm mà vẫn lo xương không chắc lên.","Tuổi càng cao, sợ loãng xương, té ngã là gãy xương.","Muốn chăm xương cho mẹ lớn tuổi nhưng không biết bổ sung gì thêm."],"cong_dung":["Hỗ trợ duy trì xương chắc khoẻ.","Giúp phòng ngừa thiếu vitamin K, góp phần duy trì sức khoẻ tốt.","Vitamin K2 dạng MK-7 từ đậu natto, viên nang chay."],"thanh_phan_chinh":"Vitamin K2 (MK-7, từ đậu natto) 120 mcg/viên","lieu_dung":"Người lớn uống 1 viên/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người đang dùng thuốc chống đông máu cần hỏi ý kiến bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"ks-coq10-100":{"noi_dau":["Leo vài tầng cầu thang đã thấy hụt hơi, tim đập nhanh.","Đang uống thuốc mỡ máu, nghe nói cơ thể dễ thiếu CoQ10.","Hay đau nửa đầu, kèm buồn nôn làm gián đoạn công việc."],"cong_dung":["Hỗ trợ sức khoẻ tim mạch.","Là chất chống oxy hoá, góp phần duy trì sức khoẻ tốt.","Khi dùng dự phòng, hỗ trợ giảm tần suất đau nửa đầu và buồn nôn, nôn đi kèm.","CoQ10 nguồn gốc tự nhiên, viên mềm bao tan trong ruột."],"thanh_phan_chinh":"Coenzyme Q10 100 mg/viên","lieu_dung":"Người lớn uống 1 viên x 2–3 lần/ngày hoặc theo chỉ dẫn của bác sĩ; dùng ít nhất 3 tháng để thấy lợi ích.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc chống đông hoặc thuốc huyết áp cần hỏi bác sĩ trước khi dùng.","Gặp bác sĩ nếu đau nửa đầu xuất hiện thường xuyên hơn hoặc buồn nôn kéo dài.","Để xa tầm tay trẻ em."]},"wn-omega369-280":{"noi_dau":["Chế độ ăn ít cá, ít hạt, lo thiếu chất béo tốt cho tim.","Da khô, tóc xơ dù đã dưỡng đủ đường.","Muốn một loại dầu cá dùng được cho cả nhà mà vẫn tiết kiệm."],"cong_dung":["Bổ sung axit béo thiết yếu omega-3, 6 và 9.","Hỗ trợ sức khoẻ tim mạch và não bộ.","Góp phần hỗ trợ hệ thần kinh và duy trì sức khoẻ tốt.","Kết hợp dầu cá, dầu hạt lanh và dầu hạt lưu ly cân đối."],"thanh_phan_chinh":"Mỗi viên: dầu cá 400 mg (EPA 70 mg, DHA 45 mg), dầu hạt lanh 400 mg, dầu hạt lưu ly 400 mg (GLA 75 mg)","lieu_dung":"Người lớn uống 1 viên x 3 lần/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người đang dùng thuốc chống đông máu nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"sesame-omega3":{"noi_dau":["Con kén ăn cá, mẹ lo bé thiếu DHA cho giai đoạn đang lớn.","Cho con uống dầu cá, bé chê tanh rồi nhè ra.","Muốn con tập trung học tốt hơn mà không biết bổ sung gì an toàn."],"cong_dung":["Bổ sung omega-3, trong đó chủ yếu là DHA cho trẻ.","Góp phần duy trì sức khoẻ tốt, tạo thói quen bổ sung dưỡng chất cho bé.","Kẹo dẻo vị cam chanh, hình Elmo, không gelatin, không màu và chất bảo quản nhân tạo."],"thanh_phan_chinh":"Mỗi viên: omega-3 50 mg (EPA 8 mg, DHA 42 mg) từ 88 mg dầu cá cơm/cá mòi","lieu_dung":"Trẻ từ 3–11 tuổi và 12–17 tuổi: nhai 2 viên/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Để xa tầm tay trẻ em, người lớn cất giữ và chia viên cho bé.","Sản phẩm có nguồn gốc từ cá, trẻ dị ứng cá cần hỏi bác sĩ trước khi dùng."]},"olay-fresh-radiance":{"noi_dau":["Tắm xong da khô căng, phải thoa kem dưỡng ngay mới dễ chịu.","Mùi sữa tắm bay nhanh, chưa hết buổi sáng đã không còn thơm.","Muốn một chai sữa tắm dùng chung cả nhà, dịu nhẹ mà dùng được lâu."],"cong_dung":["Làm sạch dịu nhẹ với chất tẩy rửa nguồn gốc thực vật.","Bổ sung phức hợp vitamin B3 và chất chống oxy hoá, giúp da mềm mại sau tắm.","Hương thơm tươi mát lưu lâu, có hai mùi hoa hồng và oải hương.","Không chứa paraben và phthalate; chai 887 ml có vòi bơm tiện dùng."],"thanh_phan_chinh":"Phức hợp vitamin B3 và chất chống oxy hoá","lieu_dung":"Cho một lượng vừa đủ ra bông tắm hoặc lòng bàn tay, tạo bọt, mát-xa khắp cơ thể rồi tắm sạch lại với nước. Dùng hằng ngày.","luu_y":["Tránh để sản phẩm dính vào mắt; nếu dính, rửa kỹ bằng nước sạch."]},"lv-belt-damier":{"noi_dau":["Muốn sắm một chiếc thắt lưng hàng hiệu mà sợ mua phải hàng không chuẩn.","Phân vân giữa kiểu dáng thời thượng và món đồ dùng được lâu năm.","Chọn quà cho chồng, bố mà lo không hợp gu, không hợp trang phục."],"cong_dung":["Mặt canvas hoạ tiết ô bàn cờ Damier Ébène nâu đặc trưng của Louis Vuitton.","Khoá chữ LV Initiales kim loại màu bạc, nổi bật mà vẫn lịch sự.","Thiết kế hai mặt: một mặt canvas Damier, một mặt da trơn, đổi phong cách dễ dàng.","Hợp cả quần âu công sở lẫn quần jeans dạo phố."],"lieu_dung":"Cắt hoặc chỉnh độ dài phù hợp vòng eo tại cửa hàng chuyên về đồ da. Sau khi dùng, lau khô, cất vào túi vải hoặc hộp kèm theo, tránh để nơi ẩm, nắng gắt và tránh tiếp xúc nước, nước hoa.","luu_y":[]},"nb-melatonin-gummy":{"noi_dau":["Nằm trằn trọc cả tiếng đồng hồ mà mắt vẫn mở thao láo.","Đi công tác, lệch múi giờ là mấy hôm liền ngủ chập chờn.","Không muốn dùng thuốc ngủ nhưng cũng cần một giấc ngủ yên."],"cong_dung":["Hỗ trợ cải thiện chất lượng giấc ngủ theo công bố trên nhãn.","Góp phần giúp điều chỉnh lại nhịp thức – ngủ của cơ thể.","Hỗ trợ giảm ảnh hưởng của lệch múi giờ khi đi xa.","Dạng kẹo dẻo vị dâu, dễ dùng cho người ngại nuốt viên."],"thanh_phan_chinh":"Melatonin 2,5 mg/viên kẹo (5 mg mỗi liều 2 viên)","lieu_dung":"Người lớn: nhai 2 viên, 1 lần/ngày, vào lúc hoặc trước giờ đi ngủ. Khi lệch múi giờ: dùng 2 viên trước khi ngủ trong chuyến đi và tại nơi đến cho tới khi cơ thể quen giờ mới.","luu_y":["Không dùng cho phụ nữ có thai hoặc đang cho con bú.","Hỏi bác sĩ nếu đang dùng thuốc chống đông, thuốc huyết áp, thuốc an thần, thuốc chống co giật hoặc có bệnh gan, thận, trầm cảm, tiểu đường.","Không dùng cùng rượu; mất ngủ kéo dài quá 4 tuần nên đi khám."]},"wn-zinc-50":{"noi_dau":["Cả nhà hay ốm vặt mỗi lần trời trở gió.","Da dễ nổi mụn, vết xước lâu lành hơn trước.","Ăn uống thất thường, sợ cơ thể thiếu khoáng chất mà không biết."],"cong_dung":["Bổ sung kẽm dạng citrate, dạng hấp thu tốt.","Hỗ trợ duy trì chức năng miễn dịch bình thường.","Góp phần duy trì làn da, tóc, móng và xương khỏe mạnh.","Hỗ trợ chuyển hóa năng lượng và hình thành mô."],"thanh_phan_chinh":"Kẽm 50 mg/viên (dạng kẽm citrate)","lieu_dung":"Người lớn: uống 1 viên/ngày cùng bữa ăn, cách các thuốc khác vài giờ, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Bổ sung kẽm có thể gây thiếu đồng; nếu không chắc lượng đồng đang dùng, hỏi nhân viên y tế trước khi dùng.","Để xa tầm tay trẻ em."]},"wn-mag-citrate":{"noi_dau":["Hay bị chuột rút bắp chân, nhất là lúc nửa đêm.","Cơ thể mỏi mệt, căng cứng dù chẳng làm việc gì nặng.","Tuổi càng lớn càng lo xương khớp và tim không còn khỏe như trước."],"cong_dung":["Bổ sung magie dạng citrate, 150 mg magie nguyên tố mỗi viên.","Hỗ trợ duy trì chức năng cơ bình thường, kể cả cơ tim.","Góp phần phát triển và duy trì xương, răng chắc khỏe.","Hỗ trợ cơ thể chuyển hóa dưỡng chất và hình thành mô."],"thanh_phan_chinh":"Magie nguyên tố 150 mg/viên (dạng magie citrate)","lieu_dung":"Người lớn: uống 1–3 viên/ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Một số người có thể bị tiêu chảy.","Để xa tầm tay trẻ em, tránh nơi nóng ẩm."]},"jms-cal-mag-d3":{"noi_dau":["Sau tuổi 40, đầu gối bắt đầu kêu lục cục khi leo cầu thang.","Mẹ lớn tuổi đi lại chậm, cả nhà lo chuyện loãng xương.","Ít uống sữa, ít ra nắng, sợ thiếu canxi mà không hay."],"cong_dung":["Bổ sung canxi và magie theo tỷ lệ 2:1 kèm vitamin D3.","Hỗ trợ phát triển và duy trì xương, răng chắc khỏe.","Vitamin D3 hỗ trợ hấp thu và sử dụng canxi, phốt pho.","Magie góp phần duy trì chức năng cơ bình thường, kể cả cơ tim.","Cùng chế độ ăn và vận động hợp lý, góp phần giảm nguy cơ loãng xương về sau."],"thanh_phan_chinh":"Canxi 333 mg, magie 167 mg, vitamin D3 200 IU mỗi viên","lieu_dung":"Người lớn: uống 1–3 viên/ngày cùng bữa ăn, cách các thuốc hoặc thực phẩm bổ sung khác vài giờ.","luu_y":["Một số người có thể bị tiêu chảy.","Phụ nữ có thai, cho con bú nên hỏi nhân viên y tế trước khi dùng.","Để xa tầm tay trẻ em."]},"wn-melatonin-5":{"noi_dau":["Đêm nào cũng nằm đếm giờ, càng cố ngủ càng tỉnh.","Làm ca, giờ giấc đảo lộn khiến giấc ngủ không còn sâu.","Sáng dậy mệt rũ vì cả đêm ngủ chập chờn."],"cong_dung":["Hỗ trợ rút ngắn thời gian đi vào giấc ngủ.","Góp phần điều chỉnh lại nhịp thức – ngủ của cơ thể.","Hỗ trợ tăng tổng thời gian ngủ khi làm ca hoặc lệch múi giờ.","Viên ngậm tan nhanh dưới lưỡi, vị bạc hà dễ chịu."],"thanh_phan_chinh":"Melatonin 5 mg/viên ngậm dưới lưỡi","lieu_dung":"Người lớn: ngậm 1–2 viên dưới lưỡi cho tan, 1 lần/ngày, chỉ dùng trước khi đi ngủ, hoặc theo chỉ dẫn của bác sĩ. Dùng quá 4 tuần nên hỏi bác sĩ.","luu_y":["Không dùng khi có thai, đang cho con bú hoặc đang dùng thuốc ức chế miễn dịch.","Hỏi bác sĩ nếu đang dùng thuốc huyết áp, thuốc an thần, hoặc có bệnh gan, thận, tiểu đường, động kinh, trầm cảm.","Không lái xe, vận hành máy móc trong 5 giờ sau khi dùng."]},"salonpas-140":{"noi_dau":["Ngồi máy tính cả ngày, vai gáy cứng đơ không quay nổi.","Bê đồ nặng một chút là lưng ê ẩm mấy hôm.","Bố mẹ đau khớp mỗi khi trở trời, cần thứ dán tiện mang theo."],"cong_dung":["Giảm tạm thời đau nhức cơ và khớp theo chỉ định trên nhãn.","Dùng cho đau lưng thông thường, cứng vai, căng cơ, bong gân.","Dùng cho vết bầm và đau do viêm khớp.","Hiệu quả kéo dài đến 8 giờ mỗi miếng dán."],"thanh_phan_chinh":"Methyl salicylate 10%, menthol 6%, camphor 3%","lieu_dung":"Người lớn và trẻ từ 12 tuổi: làm sạch, lau khô vùng đau rồi dán, không quá 2 miếng một lần, 1–2 lần/ngày; không để miếng dán trên da quá 8 giờ. Trẻ dưới 12 tuổi cần người lớn giám sát.","luu_y":["Không dán lên vết thương, da trầy xước hoặc kích ứng; không dùng cùng túi chườm nóng vì có thể gây bỏng.","Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú hoặc đang dùng thuốc chống đông.","Ngừng dùng và đi khám nếu đau, sưng, phồng rộp da hoặc triệu chứng kéo dài quá 7 ngày."]},"ensure-regular":{"noi_dau":["Bố mẹ lớn tuổi ăn ít, bữa cơm chỉ vài thìa là buông đũa.","Người mới ốm dậy mệt mỏi, chẳng muốn ăn gì.","Bận rộn bỏ bữa liên tục, lo cơ thể thiếu chất."],"cong_dung":["Bổ sung dinh dưỡng giúp duy trì năng lượng và sự năng động.","Mỗi chai cung cấp 9 g đạm và 240 Calo.","Bổ sung 27 vitamin và khoáng chất theo hộp.","Kẽm, vitamin A, C, D góp phần hỗ trợ hệ miễn dịch.","Không chứa gluten, phù hợp người không dung nạp lactose."],"thanh_phan_chinh":"Mỗi chai 235 ml: 9 g đạm, 240 Calo, 27 vitamin và khoáng chất","lieu_dung":"Uống như một bữa phụ giữa các bữa ăn hoặc dùng kèm bữa ăn. Lắc đều trước khi uống, ngon hơn khi uống lạnh.","luu_y":["Là thực phẩm bổ sung dinh dưỡng, không thay thế tư vấn của nhân viên y tế; người đang theo chế độ ăn bệnh lý nên hỏi bác sĩ."]},"tn-ginkgo-340":{"noi_dau":["Vừa đặt chìa khóa xuống đã quên mất để ở đâu.","Làm việc căng thẳng, đầu óc hay lơ mơ, khó tập trung.","Bố mẹ có tuổi hay quên trước quên sau, con cái lo lắng."],"cong_dung":["Bổ sung chiết xuất lá bạch quả tiêu chuẩn hóa.","Hỗ trợ trí nhớ và khả năng tập trung theo công bố của hãng.","Góp phần hỗ trợ tuần hoàn, lưu thông máu lên não.","Viên nang mềm dễ uống, lọ lớn dùng được lâu."],"thanh_phan_chinh":"Chiết xuất lá bạch quả (Ginkgo biloba) 120 mg/viên","lieu_dung":"Người lớn: uống 1 viên x 2 lần/ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú, đang dùng thuốc (đặc biệt thuốc chống đông) hoặc sắp phẫu thuật.","Không dành cho người dưới 18 tuổi."]},"ocuvite-50-90":{"noi_dau":["Qua tuổi 50, đọc chữ nhỏ phải đưa ra xa mới thấy.","Nhìn điện thoại một lúc là mắt mỏi, khô và nhòe.","Lo đôi mắt bố mẹ ngày càng kém mà chưa biết bổ sung gì."],"cong_dung":["Bổ sung lutein và zeaxanthin hỗ trợ sắc tố hoàng điểm.","Omega-3 góp phần duy trì nước mắt và võng mạc khỏe mạnh.","Bổ sung vitamin C, E, kẽm, đồng hỗ trợ chống oxy hóa.","Có thêm vitamin D, viên nhỏ dễ nuốt."],"thanh_phan_chinh":"Lutein 5 mg, zeaxanthin 1 mg, omega-3 250 mg, vitamin D 30 mcg mỗi viên","lieu_dung":"Uống 1 viên mỗi ngày vào buổi sáng, cùng bữa ăn với một ly nước đầy.","luu_y":["Để xa tầm tay trẻ em.","Không dùng nếu niêm phong dưới nắp bị rách hoặc mất."]},"sr-omega3-alaskan":{"noi_dau":["Ăn cá biển không thường xuyên, sợ thiếu omega-3.","Uống dầu cá loại thường hay bị ợ tanh khó chịu.","Muốn chăm sóc tim mạch cho cả nhà mà ngại uống nhiều viên."],"cong_dung":["Bổ sung omega-3 hàm lượng cao, 1040 mg mỗi viên.","Hỗ trợ sức khỏe tim mạch và hệ miễn dịch theo công bố của hãng.","Dầu cá minh thái Alaska đánh bắt tự nhiên, đạt chứng nhận MSC.","Chỉ cần 1 viên mỗi ngày."],"thanh_phan_chinh":"Dầu cá 1250 mg/viên, trong đó omega-3 1040 mg (EPA 690 mg, DHA 260 mg)","lieu_dung":"Người lớn: uống 1 viên/ngày cùng bữa ăn, hoặc theo chỉ dẫn của nhân viên y tế.","luu_y":["Hỏi nhân viên y tế trước khi dùng nếu có thai, cho con bú, đang dùng thuốc chống đông hoặc sắp phẫu thuật.","Có chứa cá; không dùng quá liều khuyến nghị."]},"olay-regenerist-set":{"noi_dau":["Soi gương thấy nếp nhăn khóe mắt ngày một rõ.","Da khô, xỉn màu, trang điểm không còn ăn phấn như trước.","Muốn chăm da kỹ hơn nhưng không có thời gian đi spa."],"cong_dung":["Niacinamide và hyaluronic acid giúp cấp ẩm, làm sáng da.","Peptide và vitamin E giúp làm mờ nếp nhăn, rãnh nhăn nhỏ.","Giúp da trông săn chắc, mịn và đều màu hơn.","Hỗ trợ củng cố hàng rào ẩm của da."],"thanh_phan_chinh":"Niacinamide (B3), sodium hyaluronate, peptide (palmitoyl pentapeptide-4), vitamin E, panthenol","lieu_dung":"Sau khi làm sạch da, lấy lượng vừa đủ thoa đều lên mặt và cổ, sáng và tối. Ban ngày nên dùng thêm kem chống nắng.","luu_y":["Có hương liệu; da nhạy cảm nên thử trên một vùng da nhỏ trước.","Tránh tiếp xúc với mắt."]},"yt-collagen-liquid":{"noi_dau":["Da mất dần độ căng, nếp nhăn xuất hiện lúc nào không hay.","Tóc rụng nhiều, móng tay mỏng và dễ gãy.","Muốn bổ sung collagen nhưng ngại pha bột mỗi sáng."],"cong_dung":["Bổ sung 5.000 mg collagen thủy phân mỗi gói, trong đó có Verisol.","Hỗ trợ làn da, tóc và móng khỏe đẹp theo công bố của hãng.","Góp phần cải thiện độ đàn hồi và làm mờ nếp nhăn.","Dạng nước uống liền, không đường, tiện mang theo."],"thanh_phan_chinh":"Collagen 5.000 mg/gói 30 ml (Verisol 2.500 mg + collagen peptide thủy phân 2.500 mg)","lieu_dung":"Người lớn: lắc đều, uống trực tiếp 1 gói mỗi ngày.","luu_y":["Không dùng khi có thai hoặc đang cho con bú; không dành cho người dưới 18 tuổi.","Hỏi bác sĩ nếu đang dùng thuốc hoặc có bệnh lý; không dùng quá liều khuyến nghị."]},"vp-collagen-gummy":{"noi_dau":["Bước qua tuổi 35, da không còn căng mịn như xưa.","Biết collagen tốt nhưng không quen uống bột hay nước.","Muốn chăm da từ bên trong bằng cách đơn giản, dễ duy trì."],"cong_dung":["Bổ sung 2,5 g collagen peptide Verisol mỗi khẩu phần.","Hỗ trợ làm mờ nếp nhăn và rãnh nhăn nhỏ theo công bố của hãng.","Góp phần cải thiện sức khỏe làn da khi dùng đều đặn.","Dạng kẹo dẻo vị mâm xôi, dễ dùng hằng ngày."],"thanh_phan_chinh":"Collagen peptide Verisol 2,5 g mỗi khẩu phần 4 viên","lieu_dung":"Nhai 4 viên mỗi khẩu phần, dùng 1 lần mỗi ngày.","luu_y":["Collagen không phải nguồn đạm hoàn chỉnh, không dùng thay thế đạm trong bữa ăn.","Để xa tầm tay trẻ em."]},"sv-lutein-10":{"noi_dau":["Cả ngày dán mắt vào màn hình, tối về mắt mỏi rã rời.","Tuổi trung niên, nhìn xa nhìn gần đều thấy kém đi.","Bố mẹ lớn tuổi, con cái lo các vấn đề mắt về già."],"cong_dung":["Bổ sung lutein kèm zeaxanthin cho sức khỏe mắt.","Hỗ trợ sức khỏe mắt trong các tình trạng như đục thủy tinh thể theo nhãn.","Góp phần hỗ trợ mắt trước thoái hóa điểm vàng do tuổi tác.","Viên nang mềm, mỗi ngày dùng gọn nhẹ."],"thanh_phan_chinh":"Lutein 10 mg/viên, có zeaxanthin","lieu_dung":"Người lớn: uống 1 viên mỗi ngày, nên dùng cùng bữa ăn. Vui lòng đối chiếu hướng dẫn trên nhãn sau lọ.","luu_y":["Phụ nữ có thai, cho con bú hoặc người đang dùng thuốc nên hỏi nhân viên y tế trước khi dùng."]},"ks-coq10-200":{"noi_dau":["Leo vài tầng cầu thang đã thấy hụt hơi, mệt mỏi.","Tuổi 40 trở đi bắt đầu lo chuyện tim mạch của bản thân và bố mẹ.","Hay đau nửa đầu, mỗi cơn kèm buồn nôn rất khó chịu."],"cong_dung":["Bổ sung CoQ10 nguồn tự nhiên, 200 mg mỗi viên.","Hỗ trợ sức khỏe tim mạch và cung cấp chất chống oxy hóa.","Dùng dự phòng giúp giảm tần suất đau nửa đầu theo công bố trên nhãn.","Viên bao tan ở ruột, giảm khó chịu cho dạ dày nhạy cảm."],"thanh_phan_chinh":"Coenzyme Q10 (ubiquinone) 200 mg/viên","lieu_dung":"Uống 1 viên mỗi ngày, hoặc theo chỉ dẫn của bác sĩ. Nên dùng ít nhất 3 tháng để thấy lợi ích.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú, đang dùng thuốc chống đông hoặc thuốc huyết áp.","Đi khám nếu cơn đau nửa đầu tăng lên hoặc buồn nôn, nôn kéo dài."]},"wn-omega369-180":{"noi_dau":["Ít ăn cá, lo cơ thể thiếu chất béo tốt cho tim và não.","Uống dầu cá hay bị ợ lên mùi tanh.","Làm việc trí óc nhiều, muốn chăm lo tim mạch và trí não cùng lúc."],"cong_dung":["Bổ sung omega-3, 6, 9 từ dầu cá, dầu hạt lanh và dầu lưu ly.","Hỗ trợ sức khỏe tim mạch và chức năng não theo công bố của hãng.","Góp phần duy trì sức khỏe tổng thể.","Viên bao tan ở ruột, hạn chế ợ tanh."],"thanh_phan_chinh":"Mỗi viên: dầu cá 400 mg (EPA 70 mg, DHA 45 mg), dầu hạt lanh 400 mg (ALA 200 mg), dầu lưu ly 400 mg","lieu_dung":"Người lớn: uống 2 viên x 3 lần/ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi bác sĩ trước khi dùng nếu đang dùng thuốc chống đông hoặc thuốc uống khác.","Để xa tầm tay trẻ em."]},"wn-acv-5000":{"noi_dau":["Ăn uống điều độ mà cân nặng vẫn nhích lên từng chút.","Ăn xong bữa cơm là bụng đầy, khó tiêu.","Thích đồ ngọt, lại lo chuyện đường huyết khi có tuổi."],"cong_dung":["Bổ sung giấm táo lên men tự nhiên có 'giấm cái' kèm crom.","Hỗ trợ duy trì đường huyết bình thường theo công bố của hãng.","Góp phần hỗ trợ chuyển hóa tinh bột và chất béo.","Hỗ trợ tiêu hóa chất béo trong bữa ăn."],"thanh_phan_chinh":"Giấm táo tương đương 5000 mg nguyên liệu thô mỗi viên, kèm crom","lieu_dung":"Người lớn: uống 1–3 viên, 1 lần/ngày, nên uống cùng bữa ăn với một ly nước đầy, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có bệnh thận hoặc tiểu đường.","Không dùng khi có thai hoặc đang cho con bú."]},"jms-vitc-chew":{"noi_dau":["Con đi học về hay sụt sịt, cả nhà lây theo.","Ăn ít rau quả, lo cơ thể không đủ vitamin C.","Trẻ con sợ uống viên, người lớn thì hay quên."],"cong_dung":["Bổ sung vitamin C, 500 mg mỗi viên nhai.","Hỗ trợ hệ miễn dịch khỏe mạnh.","Giúp phòng ngừa thiếu vitamin C.","Viên nhai vị trái cây, dùng được cho trẻ từ 4 tuổi."],"thanh_phan_chinh":"Vitamin C (acid ascorbic) 500 mg/viên","lieu_dung":"Nhai, mỗi ngày 1 lần: người lớn 1–4 viên; 14–18 tuổi 1–3 viên; 9–13 tuổi 1–2 viên; 4–8 tuổi 1 viên.","luu_y":["Nhãn chỉ có liều cho trẻ từ 4 tuổi trở lên.","Để xa tầm tay trẻ em, bảo quản ở 15–25°C."]},"lv-wallet-damier":{"noi_dau":["Sợ mua phải hàng kém chất lượng khi chọn đồ da hiệu.","Muốn một chiếc ví lịch sự, dùng lâu năm mà không lỗi mốt.","Băn khoăn ví đẹp nhưng không đủ ngăn đựng thẻ, tiền."],"cong_dung":["Họa tiết ca-rô Damier Ebene nâu kinh điển, lịch lãm.","Canvas phủ bền, hạn chế trầy và bám bẩn khi dùng hằng ngày.","Kiểu gấp đôi gọn, vừa túi quần, túi áo vest.","Bên trong có các ngăn đựng thẻ và ngăn tiền."],"lieu_dung":"Dùng hằng ngày đựng tiền, thẻ; không nhét quá dày để ví giữ dáng. Bảo quản nơi khô ráo, tránh nước và nhiệt độ cao, lau bằng khăn mềm khô, cất trong túi vải khi không dùng.","luu_y":[]},"goli-acv":{"noi_dau":["Ăn uống điều độ mà cân nặng vẫn nhích lên từng chút","Muốn dùng giấm táo mỗi ngày nhưng ngại vị chua gắt khó uống","Bận rộn cả ngày, khó duy trì một thói quen tốt cho sức khỏe"],"cong_dung":["Bổ sung giấm táo dạng kẹo dẻo, dễ dùng hơn uống giấm trực tiếp","Hai viên kẹo tương đương một lượng giấm táo uống thường ngày theo hãng","Góp phần duy trì thói quen ăn uống lành mạnh khi kết hợp chế độ hợp lý","Thuần chay, không gluten, không biến đổi gen theo nhãn"],"thanh_phan_chinh":"Giấm táo kèm bột củ dền, bột lựu hữu cơ, vitamin B9 và B12","lieu_dung":"Người lớn nhai 1–2 viên kẹo, ngày 3 lần; nên dùng sau bữa ăn.","luu_y":["Nhãn Canada có biểu tượng cảnh báo sản phẩm nhiều đường, người cần kiểm soát đường huyết nên cân nhắc.","Phụ nữ có thai, cho con bú hoặc đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng."]},"jms-iron-28":{"noi_dau":["Hay mệt, hoa mắt khi đứng lên mà không rõ vì sao","Muốn bổ sung sắt nhưng sợ táo bón, nóng rát dạ dày","Kinh nguyệt hằng tháng khiến cơ thể dễ thiếu hụt sắt"],"cong_dung":["Hỗ trợ phòng ngừa tình trạng thiếu sắt theo công bố trên nhãn","Sắt dạng bisglycinate dịu nhẹ, thân thiện với dạ dày","Bổ sung thêm acid folic, vitamin B2, B12 và C","Viên nang thực vật, không gluten, không lactose"],"thanh_phan_chinh":"Sắt (ferrous bisglycinate) 28 mg, acid folic 400 mcg, B2 800 mcg, B12 8 mcg, vitamin C 60 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn. Uống cách các thuốc hoặc sản phẩm khác vài giờ.","luu_y":["Để xa tầm tay trẻ em: lượng sắt trong hộp đủ gây hại nghiêm trọng cho trẻ.","Uống cách thuốc khác vài giờ trước hoặc sau."]},"ks-glucosamine":{"noi_dau":["Lên xuống cầu thang đầu gối cứ ê ẩm, kêu lục cục","Sáng ngủ dậy khớp cứng, phải một lúc mới cử động thoải mái","Muốn tiếp tục đi bộ, làm việc nhà mà không bị đau khớp cản trở"],"cong_dung":["Hỗ trợ giảm đau khớp liên quan đến thoái hóa khớp theo công bố nhãn Canada","Góp phần bảo vệ sụn khớp trước sự hao mòn","Hỗ trợ duy trì sụn và khớp khỏe mạnh","Hỗ trợ làm dịu cảm giác nhức mỏi khớp"],"thanh_phan_chinh":"Glucosamine sulfate 500 mg, chondroitin sulfate 400 mg, MSM 400 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên, ngày 3 lần cùng bữa ăn; dùng tối thiểu 4 tuần để thấy tác dụng, tránh uống lúc đi ngủ.","luu_y":["Nguồn gốc từ vỏ tôm, cua: người dị ứng hải sản có vỏ cần hỏi bác sĩ trước khi dùng.","Phụ nữ có thai hoặc cho con bú nên hỏi ý kiến bác sĩ.","Một số người có thể đầy hơi, táo bón hoặc khó tiêu nhẹ."]},"bragg-acv-ginger":{"noi_dau":["Muốn uống giấm táo mỗi sáng nhưng vị chua gắt khó nuốt","Tìm thức uống thanh nhẹ thay nước ngọt cho cả nhà","Ngại tự pha chế giấm, gừng, chanh mất thời gian mỗi ngày"],"cong_dung":["Giấm táo hữu cơ nguyên chất, chưa lọc, còn giữ con giấm","Pha sẵn cùng mật ong, nước cốt chanh và gừng, vị dễ uống hơn","Dùng pha nước uống hằng ngày hoặc trộn nước sốt, salad","Góp phần đa dạng thói quen uống lành mạnh trong gia đình"],"thanh_phan_chinh":"Giấm táo hữu cơ, mật ong hữu cơ, nước cốt chanh vàng, chanh xanh, gừng hữu cơ, chiết xuất cỏ ngọt","lieu_dung":"Lắc nhẹ trước khi dùng. Pha khoảng 2 thìa canh với 240 ml nước lọc hoặc nước có ga, khuấy đều; bảo quản lạnh sau khi mở.","luu_y":["Luôn pha loãng, không uống trực tiếp vì độ chua cao.","Có mật ong: không dùng cho trẻ dưới 1 tuổi."]},"wn-ubiquinol":{"noi_dau":["Bước qua tuổi 40, leo vài bậc thang đã thấy hụt hơi","Lo lắng cho sức khỏe tim mạch của bản thân và bố mẹ","Đang dùng thuốc mỡ máu, nghe nói cơ thể dễ thiếu CoQ10"],"cong_dung":["Hỗ trợ duy trì sức khỏe tim mạch theo công bố trên nhãn","Ubiquinol là dạng CoQ10 hoạt tính, cơ thể dễ hấp thu","Đóng vai trò chất chống oxy hóa, góp phần duy trì sức khỏe chung"],"thanh_phan_chinh":"Ubiquinol (CoQ10 dạng khử) 100 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên, ngày 1–3 lần hoặc theo chỉ dẫn của bác sĩ; hỏi bác sĩ nếu dùng quá 4 tuần.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú, đang dùng thuốc huyết áp, thuốc chống đông hoặc hóa trị.","Để xa tầm tay trẻ em."]},"redwin-vite":{"noi_dau":["Da tay chân khô ráp, nứt nẻ mỗi khi trời hanh","Da nhạy cảm, dùng kem lạ là dễ ngứa rát","Muốn một hũ kem dưỡng to, cả nhà dùng chung tiết kiệm"],"cong_dung":["Dưỡng ẩm cho da khô, da nhạy cảm","Chứa vitamin E tự nhiên và dầu hoa anh thảo","Giúp da mềm mại, dễ chịu hơn khi thời tiết khô hanh","Dùng được cho mặt và toàn thân"],"thanh_phan_chinh":"Vitamin E tự nhiên (từ mầm lúa mì) và dầu hoa anh thảo","lieu_dung":"Thoa đều lên da sạch, khô và massage đến khi thấm; dùng hằng ngày hoặc khi cần, nhất là sau khi tắm, rửa tay hoặc ra nắng gió.","luu_y":["Chỉ dùng ngoài da, tránh để kem dính vào mắt.","Bảo quản dưới 30°C."]},"nb-hsn-softgel":{"noi_dau":["Tóc rụng nhiều mỗi lần gội, chải đầu","Móng tay mỏng, dễ gãy, tách lớp","Da xỉn màu, thiếu sức sống dù đã chăm dưỡng bên ngoài"],"cong_dung":["Bổ sung biotin hàm lượng cao cùng nhóm vitamin cho tóc, da, móng","Có vitamin C và E chống oxy hóa, thêm hyaluronic acid","Bổ sung dầu argan và collagen thủy phân","Viên nang mềm dạng lỏng, giải phóng nhanh"],"thanh_phan_chinh":"Biotin 5.000 mcg, vitamin A, C, E, nhóm B, dầu argan 25 mg, hyaluronic acid 30 mg mỗi 3 viên","lieu_dung":"Người lớn uống 3 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Có thai, cho con bú, đang dùng thuốc, sắp phẫu thuật hoặc sắp xét nghiệm máu cần hỏi bác sĩ trước khi dùng.","Có thành phần từ đậu nành và hạt cây (argan)."]},"ks-fish-oil-wild":{"noi_dau":["Bữa cơm gia đình ít khi có cá biển","Lo lắng chỉ số mỡ máu khi khám sức khỏe định kỳ","Muốn chăm tim mạch cho bố mẹ mà không biết bắt đầu từ đâu"],"cong_dung":["Hỗ trợ sức khỏe tim mạch theo công bố của hãng","Hỗ trợ duy trì triglyceride trong ngưỡng bình thường","Dầu cá tự nhiên từ cá đánh bắt hoang dã vùng Alaska","Được USP kiểm chứng chất lượng"],"thanh_phan_chinh":"Dầu cá 1400 mg, trong đó omega-3 330 mg (EPA + DHA 230 mg) mỗi viên","lieu_dung":"Uống 1 viên mỗi ngày với một ly nước đầy, tốt nhất cùng bữa ăn.","luu_y":["Có nguồn gốc từ cá, người dị ứng cá không dùng.","Người đang dùng thuốc chống đông hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"tn-lutein-140":{"noi_dau":["Nhìn điện thoại, máy tính cả ngày, tối về mắt mỏi rát","Đọc chữ nhỏ ngày càng khó, phải đưa ra xa mới thấy","Lo đôi mắt bố mẹ yếu dần theo tuổi"],"cong_dung":["Có thể hỗ trợ thị lực khỏe mạnh theo công bố trên nhãn","Có thể giúp cải thiện độ nhạy thị giác","Hỗ trợ bảo vệ mắt khi tiếp xúc ánh sáng xanh từ màn hình","Tỷ lệ lutein và zeaxanthin 5:1 từ hoa cúc vạn thọ"],"thanh_phan_chinh":"Lutein 25 mg và đồng phân zeaxanthin 5 mg (Lutemax 2020) mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Có thành phần từ đậu nành."]},"sr-d3-k2":{"noi_dau":["Làm việc trong nhà cả ngày, ít khi ra nắng","Lo xương yếu dần khi bước vào tuổi tiền mãn kinh","Uống canxi mà không chắc cơ thể có dùng được hiệu quả"],"cong_dung":["Hỗ trợ sức khỏe xương và hệ miễn dịch theo công bố của hãng","Vitamin D3 hỗ trợ cơ thể chuyển hóa canxi","Vitamin K2 (MK-7) góp phần đưa canxi về xương","Thuần chay, D3 từ địa y, kèm dầu dừa MCT giúp hấp thu"],"thanh_phan_chinh":"Vitamin D3 125 mcg (5000 IU) và vitamin K2 dạng MK-7 100 mcg mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn, hoặc theo chỉ dẫn của chuyên gia y tế.","luu_y":["Không dùng chung với các sản phẩm vitamin D liều cao khác.","Người đang dùng thuốc chống đông (như warfarin), có thai, cho con bú hoặc có bệnh lý cần hỏi bác sĩ trước khi dùng.","Không dùng quá liều khuyến cáo."]},"olay-dark-spot":{"noi_dau":["Da tay, chân sạm màu, lốm đốm sau nhiều năm đi nắng","Vùng khuỷu tay, đầu gối thâm sạm làm ngại mặc váy áo ngắn","Dưỡng thể thường chỉ ẩm, không thấy da đều màu hơn"],"cong_dung":["Hỗ trợ làm mờ đốm sậm màu trên da cơ thể theo công bố hãng","AHA tẩy tế bào chết nhẹ, giúp bề mặt da mịn và đều màu hơn","Vitamin C và niacinamide góp phần giúp da trông sáng hơn","Dưỡng ẩm cho da toàn thân hằng ngày"],"thanh_phan_chinh":"AHA, vitamin C và niacinamide","lieu_dung":"Thoa đều lên da cơ thể sạch mỗi ngày, tốt nhất sau khi tắm; kết hợp kem chống nắng khi ra ngoài.","luu_y":["Sản phẩm có AHA có thể làm da nhạy cảm hơn với ánh nắng: dùng kem chống nắng và hạn chế phơi nắng trong thời gian dùng và một tuần sau đó.","Tránh để dính vào mắt, nếu dính rửa sạch bằng nước."]},"olly-sleep":{"noi_dau":["Nằm trằn trọc mãi mới chợp mắt được","Đầu óc cứ nghĩ chuyện nhà, chuyện cửa hàng đến khuya","Sáng dậy uể oải vì giấc ngủ chập chờn"],"cong_dung":["Hỗ trợ giấc ngủ, giúp dễ đi vào giấc ngủ hơn","Melatonin góp phần điều chỉnh nhịp ngủ – thức","L-theanine kèm thảo mộc hỗ trợ thư giãn trước khi ngủ","Dạng kẹo dẻo vị mâm xôi đen, dễ dùng"],"thanh_phan_chinh":"Melatonin 3 mg và L-theanine 100 mg mỗi 2 viên, kèm thảo mộc","lieu_dung":"Người lớn nhai 2 viên mỗi ngày một lần, vào lúc hoặc trước giờ đi ngủ.","luu_y":["Không lái xe hoặc vận hành máy móc trong 5 giờ sau khi dùng melatonin.","Hỏi chuyên gia y tế nếu dùng quá 4 tuần.","Phụ nữ có thai, cho con bú và trẻ em không tự ý dùng."]},"jms-biotin-gummy":{"noi_dau":["Tóc mỏng dần, chân tóc thưa thấy rõ khi buộc lên","Móng tay giòn, hay gãy, tách lớp","Ngại nuốt viên thuốc to mỗi ngày"],"cong_dung":["Hỗ trợ phòng ngừa thiếu hụt biotin theo công bố nhãn","Hỗ trợ tóc, da và móng khỏe mạnh","Hỗ trợ cải thiện móng tay giòn, dễ gãy","Bổ sung vitamin C và E, vị trái cây dễ dùng"],"thanh_phan_chinh":"Biotin 1.250 mcg, vitamin C 7,5 mg, vitamin E 7,5 IU mỗi viên","lieu_dung":"Người lớn nhai 2 viên mỗi ngày.","luu_y":["Phụ nữ có thai hoặc cho con bú nên hỏi chuyên gia y tế trước khi dùng.","Biotin có thể làm sai lệch một số xét nghiệm, hãy báo bác sĩ khi đi xét nghiệm.","Hỏi chuyên gia y tế nếu dùng quá 1 tháng."]},"citracal-max":{"noi_dau":["Bước sang tuổi 45, lo xương giòn dần mà không hay biết","Uống canxi loại thường hay bị đầy bụng, táo bón","Không nhớ nổi phải uống canxi trước hay sau bữa ăn"],"cong_dung":["Bổ sung canxi citrate và vitamin D3 hỗ trợ sức khỏe xương","Kèm kẽm, đồng, mangan góp phần hỗ trợ xương chắc khỏe","Canxi citrate dịu nhẹ với dạ dày theo công bố hãng","Uống được lúc no hoặc lúc đói"],"thanh_phan_chinh":"Canxi citrate và vitamin D3 25 mcg (1000 IU) mỗi 2 viên, kèm kẽm 5,5 mg, đồng 0,45 mg, mangan 1,15 mg","lieu_dung":"Người lớn uống 2 viên, ngày 2 lần, cùng hoặc không cùng bữa ăn, hoặc theo chỉ dẫn của chuyên gia y tế.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi chuyên gia y tế trước khi dùng.","Chỉ dành cho người lớn, để xa tầm tay trẻ em; không dùng quá liều khuyến cáo."]},"an-liquid-collagen":{"noi_dau":["Soi gương thấy da kém căng, nếp nhăn khóe mắt rõ hơn","Uống collagen bột hay viên thấy bất tiện, khó duy trì","Muốn chăm da từ bên trong mà không mất nhiều thời gian"],"cong_dung":["Bổ sung collagen thủy phân dạng nước, pha uống tiện lợi","Bổ sung biotin hỗ trợ tóc, da và móng","Kèm chiết xuất trái cây chống oxy hóa","Góp phần hỗ trợ làn da đủ ẩm, tươi tắn"],"thanh_phan_chinh":"Collagen 4.000 mg và biotin 500 mcg mỗi ống (theo hộp bản Canada)","lieu_dung":"Mỗi ngày dùng 1 ống: lắc đều, bẻ nắp rồi pha vào khoảng 500 ml nước, khuấy đều; không uống trực tiếp từ ống.","luu_y":["Không dùng cho phụ nữ có thai, cho con bú hoặc người dưới 18 tuổi.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Không dùng nếu ống đã bị mở."]},"sv-omega3-1200":{"noi_dau":["Hay quên trước quên sau, vừa cầm điện thoại đã quên định làm gì","Làm việc cả ngày, chiều về đầu óc mệt, khó tập trung","Cả nhà ít ăn cá, lo thiếu omega-3"],"cong_dung":["Hỗ trợ sức khỏe nhận thức và chức năng não theo công bố trên nhãn","Bổ sung omega-3 từ dầu cá","Góp phần bù đắp khi bữa ăn ít cá biển"],"thanh_phan_chinh":"Dầu cá 1200 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên, ngày 3 lần, tốt nhất cùng bữa ăn.","luu_y":["Người dị ứng cá, đang dùng thuốc chống đông, có thai hoặc cho con bú nên hỏi bác sĩ trước khi dùng."]},"pantene-10-sh":{"noi_dau":["Tóc nhuộm, uốn nhiều lần nên khô xơ, dễ gãy","Gội xong tóc rối, chải đau và rụng nhiều","Nhà đông người, chai dầu gội nhỏ dùng mấy hôm đã hết"],"cong_dung":["Dưỡng ẩm, gỡ rối và giúp tóc mượt hơn","Hỗ trợ bảo vệ màu tóc nhuộm và bảo vệ tóc khỏi nhiệt","Góp phần làm tóc chắc khỏe, bóng hơn, phục hồi hư tổn bề mặt","Có keratin, vitamin E, dầu dừa, tiền vitamin B5; không paraben, không phẩm màu"],"thanh_phan_chinh":"Keratin thủy phân, dầu dừa, vitamin E, panthenol (tiền vitamin B5)","lieu_dung":"Làm ướt tóc, lấy lượng dầu gội vừa đủ xoa đều lên tóc và da đầu tạo bọt, sau đó xả sạch; dùng kèm dầu xả cùng dòng để tóc mềm hơn.","luu_y":["Tránh để dầu gội dính vào mắt, nếu dính rửa sạch bằng nước."]},"ks-hsn-gummy":{"noi_dau":["Tóc rụng nhiều sau sinh hoặc sau những tháng căng thẳng","Móng tay mỏng, hay gãy khi làm việc nhà","Ngại uống viên nang to, muốn dạng kẹo dễ dùng hằng ngày"],"cong_dung":["Hỗ trợ tóc dày hơn theo công bố trên nhãn","Hỗ trợ móng chắc khỏe hơn","Góp phần giúp làn da khỏe mạnh","Dạng kẹo dẻo vị dâu, dễ dùng"],"lieu_dung":"Dùng theo đúng liều in trên nhãn chai; không dùng quá liều khuyến cáo.","luu_y":["Sản phẩm có biotin: báo bác sĩ khi đi xét nghiệm máu.","Phụ nữ có thai, cho con bú nên hỏi ý kiến chuyên gia y tế trước khi dùng."]},"349cdad5":{"noi_dau":["Nhìn màn hình lâu, mắt khô rát như có cát","Ngồi phòng điều hòa cả ngày, mắt cay và mỏi","Sợ thuốc nhỏ mắt có chất bảo quản gây kích ứng khi dùng nhiều lần"],"cong_dung":["Làm dịu tạm thời cảm giác khô, rát, kích ứng mắt","Bôi trơn, giữ ẩm bề mặt mắt","Không chất bảo quản, ống đơn liều dùng một lần","Được khuyên dùng cho tình trạng khô mắt sau LASIK theo hướng dẫn bác sĩ"],"thanh_phan_chinh":"Carboxymethylcellulose natri 0,5%","lieu_dung":"Vặn bẻ nắp ống, nhỏ 1–2 giọt vào mắt khi cần, sau đó bỏ ống. Khô mắt sau phẫu thuật (như LASIK) dùng theo chỉ dẫn bác sĩ mắt.","luu_y":["Ngưng dùng và hỏi bác sĩ nếu đau mắt, thay đổi thị lực, đỏ hoặc kích ứng kéo dài, hoặc triệu chứng nặng hơn hay kéo dài quá 72 giờ.","Không dùng lại ống đã mở, không để đầu ống chạm vào mắt; không dùng nếu dung dịch đổi màu hoặc vẩn đục.","Để xa tầm tay trẻ em, nếu nuốt phải cần đến cơ sở y tế ngay."]},"ks-calcium-plus":{"noi_dau":["Bước sang tuổi 40, đi cầu thang nhiều đã thấy đầu gối mỏi rã.","Ăn uống bận rộn, ít uống sữa nên lo cả nhà thiếu canxi.","Muốn bổ sung canxi cho bố mẹ nhưng ngại loại phải uống nhiều viên mỗi ngày."],"cong_dung":["Bổ sung canxi và vitamin D3 hỗ trợ phát triển, duy trì xương và răng.","Vitamin D góp phần giúp cơ thể hấp thu và sử dụng canxi tốt hơn.","Hỗ trợ duy trì chức năng cơ bình thường.","Cùng chế độ ăn lành mạnh và vận động đều, góp phần giảm nguy cơ loãng xương."],"thanh_phan_chinh":"Canxi nguyên tố 600 mg + vitamin D3 800 IU mỗi viên, kèm khoáng chất","lieu_dung":"Người lớn từ 19 tuổi: uống 1 viên mỗi ngày cùng bữa ăn, uống cách các thuốc khác vài giờ, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang dùng thuốc chống đông máu.","Không dùng nếu niêm phong dưới nắp bị rách; để xa tầm tay trẻ em."]},"cetaphil-oily":{"noi_dau":["Mới rửa mặt buổi sáng mà đến trưa da đã bóng dầu.","Lỗ chân lông vùng mũi, má cứ to dần, trang điểm khó tiệp.","Sợ sữa rửa mặt tẩy mạnh làm da căng rát, dễ kích ứng."],"cong_dung":["Làm sạch dịu nhẹ, loại bỏ dầu thừa trên da.","Giúp lỗ chân lông trông se khít hơn.","Chứa niacinamide và pro-vitamin B5, hỗ trợ giữ hàng rào bảo vệ da.","Phù hợp da hỗn hợp, da dầu và cả da nhạy cảm."],"thanh_phan_chinh":"Niacinamide (vitamin B3) và pro-vitamin B5 (panthenol)","lieu_dung":"Lấy một lượng nhỏ lên da mặt đã làm ướt, massage nhẹ nhàng rồi rửa sạch bằng nước; dùng sáng và tối.","luu_y":["Chỉ dùng ngoài da, tránh để sản phẩm dính vào mắt."]},"wn-collagen30":{"noi_dau":["Soi gương thấy vùng đuôi mắt xuất hiện nếp nhăn nhỏ.","Da mặt khô ráp, thoa kem dưỡng mà vẫn thiếu độ ẩm.","Tóc dễ gãy, móng tay mỏng và hay tách lớp."],"cong_dung":["Hỗ trợ cải thiện độ ẩm và độ đàn hồi của da.","Góp phần làm giảm nếp nhăn vùng mắt và nếp nhăn nhỏ trên mặt.","Hỗ trợ tóc chắc khỏe và móng khỏe đẹp.","Kết hợp collagen peptide Verisol với ceramide thực vật, axit hyaluronic và vitamin C."],"thanh_phan_chinh":"Collagen peptide Verisol 625 mg, ceramide thực vật 7,5 mg, axit hyaluronic 5 mg mỗi viên, kèm biotin","lieu_dung":"Người lớn: uống 2 viên x 2 lần mỗi ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai hoặc cho con bú.","Có thể gây khó chịu nhẹ ở dạ dày; biotin có thể ảnh hưởng kết quả xét nghiệm, hãy báo bác sĩ.","Có chiết xuất từ hạt lúa mì, người dị ứng lúa mì cần lưu ý."]},"ks-d3-2x360":{"noi_dau":["Làm việc trong nhà cả ngày, hầu như không ra nắng.","Lo xương khớp yếu dần theo tuổi mà không biết bổ sung gì.","Hay bị ốm vặt mỗi khi giao mùa, cả nhà thay nhau mệt."],"cong_dung":["Bổ sung vitamin D3, một vitamin thiết yếu cho cơ thể.","Hỗ trợ duy trì xương và răng chắc khỏe.","Góp phần giúp hấp thu và sử dụng canxi, phốt pho.","Hỗ trợ chức năng miễn dịch."],"thanh_phan_chinh":"Vitamin D3 25 mcg (1000 IU) mỗi viên","lieu_dung":"Người lớn: uống 1 viên mỗi ngày.","luu_y":["Không dùng nếu niêm phong dưới nắp bị rách.","Bảo quản ở 15–25°C, để xa tầm tay trẻ em."]},"ks-lutein-25":{"noi_dau":["Nhìn màn hình điện thoại, máy tính cả ngày, tối về mắt mỏi nhức.","Tuổi càng cao, đọc chữ nhỏ càng thấy mờ và chói.","Lo cho mắt của bố mẹ khi tuổi già mà chưa biết bắt đầu từ đâu."],"cong_dung":["Hỗ trợ sức khỏe mắt nhờ giúp lọc ánh sáng xanh.","Hỗ trợ mắt trong các tình trạng như đục thủy tinh thể, thoái hóa điểm vàng tuổi già.","Góp phần cải thiện mật độ sắc tố điểm vàng, theo nghiên cứu hãng công bố.","Chiết xuất từ hoa cúc vạn thọ, dùng 1 viên mỗi ngày tiện lợi."],"thanh_phan_chinh":"Lutein 25 mg, zeaxanthin và meso-zeaxanthin mỗi loại 2,5 mg mỗi viên","lieu_dung":"Uống 1 viên mỗi ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai hoặc cho con bú.","Không dùng nếu niêm phong dưới nắp bị rách."]},"ricola":{"noi_dau":["Nói nhiều cả ngày, chiều về cổ họng khô rát.","Thời tiết đổi mùa là cổ họng ngứa, ho húng hắng.","Muốn có viên kẹo ngậm dễ chịu mang theo trong túi xách."],"cong_dung":["Kẹo ngậm làm dịu cổ họng, hỗ trợ giảm ho thông thường.","Kết hợp tinh dầu bạc hà và hỗn hợp thảo mộc vùng núi Thụy Sĩ.","Mang lại cảm giác mát dịu, thơm vị cherry hoặc chanh bạc hà.","Vị Lemon Mint không thêm đường, có bổ sung vitamin C."],"thanh_phan_chinh":"Menthol từ bạc hà và chiết xuất hỗn hợp thảo mộc (tía tô đất, cỏ xạ hương, xô thơm, hoa đoạn…)","lieu_dung":"Người lớn và trẻ từ 12 tuổi: ngậm tan từ từ từng viên, không nhai; vị Cherry ngậm 1 viên mỗi 1–2 giờ. Không quá 10 viên mỗi ngày.","luu_y":["Ngưng dùng và hỏi ý kiến nhân viên y tế nếu ho nặng hơn, kéo dài quá 7 ngày hoặc kèm sốt.","Vị Lemon Mint có chất tạo ngọt aspartame, người bệnh phenylketon niệu không nên dùng."]},"nb-hsn-gummy":{"noi_dau":["Mỗi lần chải đầu lại thấy tóc rụng vương đầy lược.","Móng tay mỏng, dễ gãy, sơn móng cũng không giữ được lâu.","Ngại uống viên thuốc to, muốn loại dễ dùng mỗi ngày."],"cong_dung":["Bổ sung biotin hàm lượng cao hỗ trợ tóc, da và móng.","Có vitamin A cùng vitamin C, E chống oxy hóa hỗ trợ làn da.","Dạng kẹo dẻo vị dâu dễ nhai, dễ duy trì mỗi ngày.","Không biến đổi gen (Non-GMO)."],"thanh_phan_chinh":"Biotin 6.000 mcg mỗi 2 viên kẹo, kèm vitamin A, C, E","lieu_dung":"Người lớn: nhai 2 viên kẹo mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ mang thai, cho con bú, người có bệnh lý hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng.","Biotin liều cao có thể làm sai lệch một số xét nghiệm máu, hãy báo bác sĩ khi đi xét nghiệm."]},"ks-cal-citrate":{"noi_dau":["Hay bị chuột rút bắp chân lúc nửa đêm.","Dạ dày yếu, uống canxi thường hay thấy đầy bụng khó chịu.","Phụ nữ tuổi tiền mãn kinh lo xương ngày một yếu đi."],"cong_dung":["Bổ sung canxi citrate hỗ trợ xương và răng chắc khỏe.","Vitamin D3 góp phần giúp hấp thu canxi.","Magie và kẽm hỗ trợ quá trình tạo xương, co cơ bình thường.","Kẽm góp phần hỗ trợ hệ miễn dịch."],"thanh_phan_chinh":"Canxi (citrate) 500 mg, magie 80 mg kèm kẽm và vitamin D3 trong mỗi 2 viên","lieu_dung":"Uống 2 viên mỗi ngày, hoặc theo khuyến nghị của bác sĩ.","luu_y":["Người đang dùng thuốc hoặc có bệnh lý nên hỏi ý kiến bác sĩ trước khi dùng."]},"sr-multi-collagen":{"noi_dau":["Da mặt kém căng mịn hơn hẳn so với vài năm trước.","Tóc khô xơ, mỏng dần, buộc tóc thấy nhỏ hẳn đi.","Muốn uống collagen nhưng ngại pha bột mỗi sáng."],"cong_dung":["Hỗ trợ tóc và da khỏe mạnh.","Kết hợp 5 loại collagen (I, II, III, V, X) trong một viên nang.","Bổ sung biotin, axit hyaluronic và vitamin C hỗ trợ làn da.","Không gluten, không đậu nành, không biến đổi gen."],"thanh_phan_chinh":"Hỗn hợp Multi Collagen 1.600 mg và biotin 3.000 mcg mỗi 3 viên","lieu_dung":"Người lớn: uống 3 viên mỗi ngày, có thể uống cùng hoặc không cùng bữa ăn.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai, cho con bú, có bệnh lý hoặc đang dùng thuốc.","Biotin có thể ảnh hưởng kết quả xét nghiệm, hãy báo bác sĩ khi đi xét nghiệm."]},"ks-vitc-1000":{"noi_dau":["Thời tiết thay đổi là người mệt mỏi, dễ cảm cúm.","Công việc căng thẳng, ăn ít rau quả nên lo thiếu vitamin.","Muốn bổ sung vitamin C cho cả nhà mà tiện, đỡ tốn kém."],"cong_dung":["Bổ sung vitamin C, chất chống oxy hóa giúp duy trì sức khỏe tốt.","Dạng giải phóng chậm, phóng thích vitamin C từ từ trong ngày.","Có thêm chiết xuất quả tầm xuân (rose hips).","Hộp lớn 500 viên dùng được lâu dài."],"thanh_phan_chinh":"Vitamin C 1000 mg giải phóng chậm, tầm xuân 40 mg mỗi viên","lieu_dung":"Người từ 9 tuổi trở lên: uống 1 viên mỗi ngày, hoặc theo chỉ dẫn của nhân viên y tế.","luu_y":["Không dùng nếu niêm phong dưới nắp bị rách hoặc mất.","Bảo quản ở 15–30°C."]},"tn-cinsulin":{"noi_dau":["Đi khám sức khỏe, bác sĩ dặn phải để ý đường huyết.","Đã cố bớt đồ ngọt, cơm trắng mà vẫn lo lắng.","Muốn tìm thêm giải pháp tự nhiên hỗ trợ bên cạnh ăn uống điều độ."],"cong_dung":["Hỗ trợ duy trì đường huyết khỏe mạnh trong ngưỡng bình thường.","Góp phần hỗ trợ chuyển hóa đường.","Chiết xuất quế bằng nước theo công nghệ được cấp bằng sáng chế.","Bổ sung thêm crom và vitamin D3."],"thanh_phan_chinh":"Chiết xuất vỏ quế 500 mg, crom 400 mcg, vitamin D3 500 IU mỗi 2 viên","lieu_dung":"Uống 2 viên một lần mỗi ngày với nước, trong bữa ăn.","luu_y":["Không dùng cho phụ nữ mang thai, cho con bú hoặc người dị ứng quế.","Người tiểu đường, hạ đường huyết chỉ dùng khi có theo dõi của bác sĩ.","Hỏi ý kiến bác sĩ nếu đang dùng thuốc hoặc có bệnh lý."]},"nb-vite-400":{"noi_dau":["Da khô, kém tươi tắn dù đã chăm dưỡng ngoài.","Ăn uống thất thường, lo thiếu vitamin chống oxy hóa.","Muốn bổ sung vitamin E loại uống 1 viên mỗi ngày cho tiện."],"cong_dung":["Bổ sung vitamin E, yếu tố góp phần duy trì sức khỏe tốt.","Vitamin E là chất chống oxy hóa cho cơ thể.","Không chứa chất bảo quản.","Hộp lớn 200 viên dùng được lâu."],"thanh_phan_chinh":"Vitamin E (dl-alpha tocopheryl acetat) 400 IU mỗi viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Không dùng nếu đang mang thai hoặc cho con bú (theo nhãn Canada).","Người đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng."]},"yt-k2d3-gummy":{"noi_dau":["Lo xương yếu dần theo tuổi nhưng ngại uống thêm viên thuốc.","Ít ra nắng, sợ cơ thể thiếu vitamin D.","Muốn bổ sung vitamin mà không nạp thêm đường."],"cong_dung":["Hỗ trợ sức khỏe xương và hệ miễn dịch.","Kết hợp vitamin D3 và vitamin K2 dạng MK-7.","Kẹo dẻo vị đào, không đường, dễ dùng mỗi ngày."],"lieu_dung":"Người lớn: nhai 1 viên kẹo mỗi ngày.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang dùng thuốc (đặc biệt thuốc chống đông) hoặc có bệnh lý.","Không dùng khi mang thai, cho con bú; không dành cho người dưới 18 tuổi."]},"jms-cal-mag-zinc":{"noi_dau":["Hay bị chuột rút, mỏi cơ sau một ngày đứng nhiều.","Phụ nữ sau sinh, tiền mãn kinh lo xương ngày càng yếu.","Muốn một viên bổ sung đủ canxi, magie, kẽm cho gọn."],"cong_dung":["Hỗ trợ phát triển và duy trì xương, răng.","Góp phần duy trì chức năng cơ bình thường, kể cả cơ tim.","Kẽm hỗ trợ miễn dịch, da, tóc và móng khỏe.","Cùng vitamin D và vận động, góp phần giảm nguy cơ mất xương về sau."],"thanh_phan_chinh":"Canxi 333 mg, magie 167 mg, kẽm 17 mg mỗi viên","lieu_dung":"Người lớn: uống 1–3 viên mỗi ngày cùng bữa ăn, cách các thuốc khác vài giờ.","luu_y":["Một số người có thể bị tiêu chảy.","Bổ sung kẽm có thể gây thiếu đồng."]},"ks-omega3-1300":{"noi_dau":["Tuổi trung niên, đi khám thấy mỡ máu bắt đầu nhích lên.","Hay quên, làm việc lâu là đầu óc mệt mỏi.","Uống dầu cá loại thường hay bị ợ tanh khó chịu."],"cong_dung":["Hỗ trợ chức năng tim mạch và não bộ.","Góp phần hỗ trợ giảm triglyceride trong máu.","Hỗ trợ kháng viêm, cung cấp axit béo omega-3.","Viên bao tan trong ruột giúp hạn chế ợ tanh."],"thanh_phan_chinh":"Dầu cá 1300 mg với EPA 450 mg và DHA 300 mg mỗi viên","lieu_dung":"Người lớn từ 18 tuổi: uống 1 viên mỗi ngày cho tim mạch, não bộ; 2 viên mỗi ngày để hỗ trợ giảm triglyceride, hoặc theo chỉ dẫn bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai, cho con bú, dùng thuốc chống đông hoặc có bệnh lý."]},"sr-omega3-150":{"noi_dau":["Ít ăn cá biển, lo cả nhà thiếu omega-3.","Mỗi ngày phải uống nhiều viên dầu cá thấy ngại.","Sợ dầu cá kém chất lượng, không rõ nguồn gốc."],"cong_dung":["Bổ sung omega-3 nồng độ cao chỉ với 1 viên mỗi ngày.","Hỗ trợ sức khỏe tim mạch, não bộ và thị lực.","Dầu cá đánh bắt tự nhiên, nguồn khai thác bền vững.","Không biến đổi gen, được kiểm nghiệm bởi bên thứ ba."],"thanh_phan_chinh":"Dầu cá 1250 mg, tổng omega-3 1055 mg mỗi viên","lieu_dung":"Người lớn: uống 1 viên mỗi ngày cùng bữa ăn, hoặc theo khuyến nghị của chuyên gia y tế.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai, cho con bú, dùng thuốc hoặc có bệnh lý."]},"pantene-10-cn":{"noi_dau":["Tóc nhuộm, uốn nhiều lần nên khô xơ, dễ rối.","Gội xong tóc bết hoặc xù, mất cả buổi để chải.","Muốn một chai dùng lâu cho cả nhà mà vẫn mượt tóc."],"cong_dung":["Công thức 10 trong 1: dưỡng ẩm, gỡ rối, làm mượt và làm mềm tóc.","Hỗ trợ bảo vệ màu tóc nhuộm và bảo vệ tóc khỏi nhiệt.","Giúp tóc chắc khỏe, bóng hơn, phục hồi hư tổn.","Chứa keratin, vitamin E, dầu dừa và pro-vitamin B5."],"thanh_phan_chinh":"Keratin thủy phân, dầu dừa, vitamin E, pro-vitamin B5","lieu_dung":"Sau khi gội, thoa dầu xả lên tóc ướt từ thân đến ngọn, để khoảng 1–3 phút rồi xả sạch với nước.","luu_y":["Tránh để sản phẩm dính vào mắt; nếu dính, rửa sạch bằng nước."]},"tylenol-ultra":{"noi_dau":["Cơn đau đầu ập đến giữa giờ làm, khó tập trung.","Đau nửa đầu khiến cả ngày mệt mỏi, chỉ muốn nằm.","Cần sẵn thuốc trong nhà khi người thân bị sốt."],"cong_dung":["Giảm tạm thời đau nhẹ đến vừa do đau đầu, đau nửa đầu.","Hạ sốt.","Caffeine giúp tăng hiệu quả giảm đau đầu của acetaminophen.","Viên eZ Tabs nhỏ, dễ nuốt."],"thanh_phan_chinh":"Acetaminophen (paracetamol) 500 mg + caffeine 65 mg mỗi viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi 4–6 giờ; nếu không đỡ, liều sau có thể uống 2 viên. Không quá 8 viên trong 24 giờ.","luu_y":["Quá liều có thể gây tổn thương gan nghiêm trọng; không dùng chung với thuốc khác chứa acetaminophen/paracetamol, hỏi bác sĩ nếu uống rượu thường xuyên hoặc bệnh gan, thận.","Tránh dùng thêm đồ uống, thuốc có caffeine; hỏi bác sĩ nếu tăng huyết áp, glôcôm, đang mang thai hoặc cho con bú.","Đi khám nếu triệu chứng kéo dài quá 5 ngày; để xa tầm tay trẻ em."]},"ad728e60":{"noi_dau":["Nhìn màn hình lâu, mắt khô rát và cộm như có cát.","Ngồi phòng máy lạnh cả ngày, chiều về mắt đỏ, mỏi.","Đi đường gió bụi, nắng gắt khiến mắt cay khó chịu."],"cong_dung":["Giảm tạm thời cảm giác nóng rát, kích ứng, khó chịu do khô mắt.","Làm dịu mắt khi tiếp xúc gió hoặc nắng.","Bộ nhiều lọ tiện để ở nhà, văn phòng, ô tô và mang theo."],"thanh_phan_chinh":"Carboxymethylcellulose natri 0,5%","lieu_dung":"Nhỏ 1–2 giọt vào mắt bị khô khi cần.","luu_y":["Không chạm đầu lọ vào bất kỳ bề mặt nào; đậy nắp sau khi dùng; không dùng nếu dung dịch đổi màu hoặc vẩn đục.","Ngưng dùng và đi khám nếu đau mắt, thay đổi thị lực, mắt đỏ kéo dài hoặc không đỡ sau 72 giờ.","Để xa tầm tay trẻ em; nếu nuốt phải, đến cơ sở y tế ngay."]},"250f6247":{"noi_dau":["Bữa ăn hằng ngày ít cá biển, lo thiếu omega-3 cho cả nhà","Tuổi trung niên, muốn chăm sóc tim mạch từ sớm nhưng chưa biết bắt đầu","Mua từng loại dầu cá, dầu hạt lanh riêng lẻ vừa tốn vừa khó nhớ"],"cong_dung":["Bổ sung omega-3, 6, 9 từ dầu cá, dầu hạt lanh và dầu cây lưu ly","Hỗ trợ sức khỏe tim mạch theo công bố trên nhãn","Góp phần hỗ trợ não bộ, mắt, khớp và da","Hộp lớn 325 viên, dùng được lâu cho cả gia đình"],"thanh_phan_chinh":"Tổng dầu 1600 mg mỗi khẩu phần 2 viên, trong đó khoảng 1030 mg omega-3","lieu_dung":"Người lớn uống 2 viên mỗi ngày, cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc, nhất là thuốc chống đông, nên hỏi bác sĩ trước khi dùng.","Chỉ dành cho người lớn."]},"8c9c621c":{"noi_dau":["Ngồi phòng máy lạnh cả ngày, môi khô căng và bong tróc","Đi nắng về môi rát, son màu thoa lên càng khó chịu","Muốn son dưỡng thành phần tự nhiên, dùng được cho cả nhà"],"cong_dung":["Dưỡng ẩm, giúp môi mềm và đỡ khô nứt","Thành phần nguồn gốc tự nhiên, có sáp ong","Thỏi Soothing Aloe giúp làm dịu môi sau khi đi nắng","Bộ 10 thỏi nhiều hương, tiện để túi xách, xe, văn phòng"],"thanh_phan_chinh":"Sáp ong (Beeswax) cùng dầu thực vật; thỏi Soothing Aloe có lô hội","lieu_dung":"Thoa trực tiếp lên môi bất cứ khi nào thấy khô, có thể dùng nhiều lần trong ngày.","luu_y":["Ngưng dùng nếu môi bị kích ứng.","Bảo quản nơi thoáng mát, tránh để trong xe nắng nóng làm chảy son."]},"dbe37bda":{"noi_dau":["Ngày nóng ẩm, vùng kín dễ có mùi khiến mình mất tự tin","Dùng sữa tắm thường cho vùng kín, sợ không hợp và gây khô rát","Muốn sản phẩm dịu nhẹ, mùi thơm thanh để dùng mỗi ngày"],"cong_dung":["Làm sạch nhẹ nhàng vùng kín bên ngoài, giúp loại bỏ vi khuẩn gây mùi","Độ pH cân bằng, đã được bác sĩ phụ khoa kiểm nghiệm","Không chứa phẩm màu và paraben","Hương Amber Nights dịu nhẹ, giữ cảm giác tươi mát"],"lieu_dung":"Làm ướt vùng cần vệ sinh, cho một lượng nhỏ ra tay hoặc khăn, thoa nhẹ ở vùng kín bên ngoài rồi rửa sạch lại bằng nước.","luu_y":["Chỉ dùng bên ngoài, không dùng thụt rửa bên trong.","Ngưng dùng nếu bị kích ứng, ngứa rát."]},"2f1df144":{"noi_dau":["Thời tiết thay đổi, cả nhà thay nhau hắt hơi sổ mũi","Ngại nuốt viên to, uống vitamin mãi không đều","Ăn rau quả chưa đủ mỗi ngày, lo thiếu vitamin C"],"cong_dung":["Bổ sung vitamin C dạng kẹo dẻo vị cam, dễ dùng","Hỗ trợ hệ miễn dịch theo công bố trên nhãn","Đạt chứng nhận USP Verified","Phù hợp người lớn ngại uống viên nén"],"thanh_phan_chinh":"Vitamin C 250 mg mỗi khẩu phần 2 viên kẹo","lieu_dung":"Người lớn nhai 2 viên kẹo mỗi ngày, nên dùng cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng.","Ngưng dùng và hỏi bác sĩ nếu có phản ứng bất thường.","Sản phẩm dành cho người lớn, để xa tầm tay trẻ em."]},"8086c999":{"noi_dau":["Làm việc cả ngày, chiều về người uể oải thiếu năng lượng","Ăn chay hoặc ít ăn thịt, lo thiếu vitamin B12","Tuổi càng cao, cơ thể hấp thu B12 từ thức ăn kém dần"],"cong_dung":["Bổ sung vitamin B12 dạng methylcobalamin, dạng có hoạt tính sinh học","Hỗ trợ chuyển hóa thức ăn thành năng lượng","Viên ngậm tan nhanh dưới lưỡi, không cần nuốt viên to","Đạt chứng nhận USP, lọ 300 viên dùng được lâu"],"thanh_phan_chinh":"Vitamin B12 (methylcobalamin) 2500 mcg/viên","lieu_dung":"Người lớn dùng 1 viên mỗi ngày, ngậm dưới lưỡi khoảng 30 giây rồi nuốt.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"8454cb56":{"noi_dau":["Da bé mỏng, tắm sữa tắm thường hay khô và ửng đỏ","Gội đầu cho bé, sợ xà phòng chảy vào mắt làm bé khóc","Muốn một chai dùng cả tóc lẫn người cho gọn mà vẫn dịu"],"cong_dung":["Làm sạch nhẹ nhàng cả tóc và cơ thể bé","Không cay mắt, không xà phòng, độ pH cân bằng","Có glycerin và panthenol giúp giữ ẩm cho da bé","Công thức ít gây dị ứng, không paraben"],"thanh_phan_chinh":"Glycerin và Panthenol (tiền vitamin B5)","lieu_dung":"Cho một lượng vừa đủ ra tay hoặc khăn, thoa lên tóc và người bé, tạo bọt nhẹ rồi tắm sạch và lau khô.","luu_y":["Chỉ dùng ngoài da.","Bảo quản dưới 30 độ C."]},"269d3a23":{"noi_dau":["Mấy ngày không đi ngoài được, bụng đầy nặng khó chịu","Ngồi văn phòng ít vận động, ăn ít rau là lại táo bón","Sợ thuốc nhuận tràng gây đau quặn bụng, đi ngoài gấp"],"cong_dung":["Giảm táo bón thỉnh thoảng xảy ra theo chỉ định trên nhãn","Làm mềm phân nhờ giữ nước trong ruột (nhuận tràng thẩm thấu)","Dạng bột không mùi, không vị, hòa tan vào đồ uống","Thường có tác dụng sau 1 đến 3 ngày"],"thanh_phan_chinh":"Polyethylene Glycol 3350, 17 g mỗi liều","lieu_dung":"Người lớn và trẻ từ 17 tuổi: mỗi ngày 1 lần, đong bột đến vạch 17 g trên nắp, hòa tan vào 120–240 ml nước hoặc đồ uống rồi uống ngay; không dùng quá 7 ngày. Trẻ từ 16 tuổi trở xuống: hỏi bác sĩ.","luu_y":["Không dùng nếu dị ứng polyethylene glycol; người bệnh thận chỉ dùng khi có bác sĩ theo dõi.","Ngưng dùng và hỏi bác sĩ nếu chảy máu trực tràng, tiêu chảy, đau bụng tăng hoặc cần dùng quá 7 ngày.","Phụ nữ có thai, cho con bú hỏi ý kiến chuyên môn trước khi dùng."]},"be45d3d3":{"noi_dau":["Ngồi máy tính lâu, cổ vai gáy mỏi cứng mỗi tối","Bố mẹ lớn tuổi hay nhức mỏi lưng, khớp khi trở trời","Tập thể thao xong, bắp cơ căng đau mấy ngày liền"],"cong_dung":["Giảm tạm thời đau nhẹ ở cơ và khớp theo chỉ định trên nhãn","Dùng cho đau lưng, căng cơ, bong gân, bầm tím, chuột rút","Giảm tạm thời đau nhức nhẹ do viêm khớp","Kết hợp 3 hoạt chất tạo cảm giác nóng lạnh tại chỗ đau"],"thanh_phan_chinh":"Camphor 4%, Menthol 10%, Methyl Salicylate 30%","lieu_dung":"Người lớn và trẻ từ 12 tuổi: thoa lên vùng đau, không quá 3–4 lần mỗi ngày. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Chỉ dùng ngoài da; không thoa lên vết thương, da tổn thương; không dùng cùng túi chườm nóng, không băng kín.","Tránh để dính vào mắt, niêm mạc; ngưng dùng nếu da kích ứng hoặc đau kéo dài quá 7 ngày.","Người dị ứng salicylat (aspirin) không nên dùng; nếu lỡ nuốt phải, đến cơ sở y tế ngay."]},"67e2ecd1":{"noi_dau":["Bé nghịch cả ngày, tắm gội mỗi tối mất nhiều thời gian","Tóc bé dễ rối, gỡ tóc sau khi gội là bé khóc","Sợ dầu gội cay mắt khiến bé sợ tắm"],"cong_dung":["Một chai 3 tác dụng: gội, xả và tắm cho bé","Công thức không cay mắt, đã kiểm nghiệm da liễu","Không chứa paraben, hương dưa hấu bé thích","Chai vòi nhấn 1,18 L tiện dùng cho cả nhà có nhiều bé"],"lieu_dung":"Lấy một lượng nhỏ cỡ viên kẹo, xoa lên tóc và người bé đã làm ướt cho ra bọt, sau đó xả sạch bằng nước.","luu_y":["Nếu dính vào mắt, rửa sạch bằng nước."]},"63daf11b":{"noi_dau":["Thỉnh thoảng đau đầu, đau cơ, muốn có sẵn thuốc giảm đau nhẹ","Được bác sĩ chỉ định dùng aspirin liều thấp, mua lẻ từng vỉ bất tiện","Lo viên aspirin gây khó chịu dạ dày khi phải dùng lâu"],"cong_dung":["Giảm tạm thời các cơn đau nhẹ như đau đầu, đau cơ, đau răng","Viên bao tan trong ruột, hàm lượng thấp 81 mg","Nhãn ghi dùng aspirin cho tim mạch phải hỏi bác sĩ trước","Bộ 2 lọ, tổng 730 viên, tiện cho người được kê dùng lâu dài"],"thanh_phan_chinh":"Aspirin 81 mg/viên (thuốc giảm đau nhóm NSAID)","lieu_dung":"Người lớn và trẻ từ 12 tuổi (giảm đau): uống 4–8 viên mỗi 4 giờ với một cốc nước đầy, không quá 48 viên trong 24 giờ trừ khi bác sĩ chỉ định. Trẻ dưới 12 tuổi: hỏi bác sĩ. Dùng hằng ngày cho tim mạch chỉ khi có bác sĩ chỉ định.","luu_y":["Trẻ em và thiếu niên đang hoặc vừa khỏi thủy đậu, cúm không được dùng (nguy cơ hội chứng Reye).","Có thể gây chảy máu dạ dày, nhất là người trên 60 tuổi, có tiền sử loét dạ dày, uống từ 3 ly rượu mỗi ngày hoặc đang dùng thuốc chống đông, corticoid.","Không dùng trong 3 tháng cuối thai kỳ trừ khi bác sĩ chỉ định."]},"1b308146":{"noi_dau":["Trước kỳ kinh hay căng tức ngực, người bứt rứt khó chịu","Ngoài 35 tuổi, da khô và kém mịn hơn trước","Muốn chăm sóc sức khỏe phụ nữ bằng sản phẩm nguồn gốc thực vật"],"cong_dung":["Bổ sung dầu hoa anh thảo ép lạnh, nguồn GLA tự nhiên","Hỗ trợ sức khỏe phụ nữ trong chu kỳ hằng tháng","Góp phần hỗ trợ làn da khỏe và đủ ẩm","Viên nang mềm giải phóng nhanh, dễ uống"],"thanh_phan_chinh":"Dầu hoa anh thảo 1000 mg/viên (nguồn axit gamma-linolenic GLA)","lieu_dung":"Người lớn uống 1 viên, 1 đến 3 lần mỗi ngày, nên uống cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc, nhất là thuốc chống đông, nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"0dcf196a":{"noi_dau":["Nghẹt mũi về đêm, phải thở bằng miệng nên ngủ không sâu","Chồng ngáy to cả đêm, vợ trằn trọc mất ngủ theo","Bị cảm, viêm mũi dị ứng, không muốn dùng thêm thuốc"],"cong_dung":["Giúp mở rộng đường thở qua mũi tức thì, không dùng thuốc","Giảm tạm thời nghẹt mũi do cảm lạnh, dị ứng, lệch vách ngăn","Giúp giảm tiếng ngáy do nghẹt mũi","Bản Extra Strength trong suốt, độ đàn hồi mạnh, hợp da nhạy cảm"],"thanh_phan_chinh":"Không chứa thuốc (dải dán đàn hồi)","lieu_dung":"Rửa sạch, lau khô sống mũi, dán 1 miếng ngang cánh mũi; có thể đeo đến 12 giờ. Khi gỡ, làm ướt bằng nước ấm rồi bóc nhẹ.","luu_y":["Không dán lên da đang kích ứng, cháy nắng hoặc có vết thương; ngưng dùng nếu da bị kích ứng.","Ngáy kéo dài có thể là dấu hiệu bệnh lý, nên đi khám nếu ngáy kèm ngưng thở khi ngủ."]},"b9ca3da4":{"noi_dau":["Ngoài 35 tuổi, soi gương thấy da kém căng, nếp nhăn rõ dần","Thức khuya, áp lực công việc làm da xỉn và thiếu sức sống","Ngại uống collagen dạng bột vì mùi tanh, pha mất công"],"cong_dung":["Bổ sung peptide collagen Verisol có hoạt tính sinh học","Hỗ trợ làn da căng sáng, rạng rỡ theo công bố trên nhãn","Góp phần làm giảm vẻ ngoài và độ sâu của nếp nhăn","Dạng viên nang, không mùi, tiện mang theo"],"thanh_phan_chinh":"Peptide collagen Verisol","lieu_dung":"Uống theo khẩu phần ghi trên nhãn, thường dùng mỗi ngày cùng nước; nên dùng đều đặn để thấy hiệu quả.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"7aca99c0":{"noi_dau":["Chạy việc ngoài trời nắng, áo ướt mồ hôi và có mùi","Lăn khử mùi thường để lại vệt trắng trên áo tối màu","Da nách nhạy cảm, dùng sản phẩm mạnh là rát ngứa"],"cong_dung":["Giảm tiết mồ hôi và khử mùi vùng nách, bảo vệ đến 72 giờ","Dạng gel trong suốt, hạn chế vệt trắng trên áo","Công thức không gây kích ứng theo công bố của hãng","Hương Cool Wave mát, nam tính"],"thanh_phan_chinh":"Aluminum Zirconium Octachlorohydrex Gly (hoạt chất chống mồ hôi)","lieu_dung":"Thoa lên vùng nách sạch và khô, chỉ dùng cho vùng dưới cánh tay.","luu_y":["Không dùng trên da bị trầy xước; ngưng dùng nếu nổi mẩn, kích ứng.","Người có bệnh thận nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"ad2ad628":{"noi_dau":["Cảm cúm vừa sốt, đau họng, nghẹt mũi mà vẫn phải đi làm","Ban đêm ho, sổ mũi liên tục khiến cả nhà mất ngủ","Mua mỗi triệu chứng một loại thuốc, uống lẫn lộn dễ quá liều"],"cong_dung":["Viên ngày: giảm tạm thời đau đầu, sốt, đau họng, đau nhức nhẹ","Viên ngày: giảm nghẹt mũi, ho và giúp long đờm","Viên đêm: giảm sốt, đau, nghẹt mũi, hắt hơi, sổ mũi và ho","Bộ ngày và đêm riêng biệt, viên ngày không gây buồn ngủ"],"thanh_phan_chinh":"Viên ngày: Acetaminophen 325 mg, Dextromethorphan HBr 10 mg, Guaifenesin 200 mg, Phenylephrine HCl 5 mg. Viên đêm: Acetaminophen 325 mg, Dextromethorphan HBr 10 mg, Doxylamine succinate 6,25 mg, Phenylephrine HCl 5 mg","lieu_dung":"Người lớn và trẻ từ 12 tuổi: mỗi lần 2 viên, cách nhau 4 giờ; không dùng quá 8 viên trong 24 giờ (tính chung cả viên ngày và viên đêm). Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Có acetaminophen: không dùng cùng thuốc khác chứa acetaminophen (paracetamol); uống quá liều hoặc kèm từ 3 ly rượu mỗi ngày có thể gây tổn thương gan nặng.","Không dùng nếu đang hoặc vừa ngưng thuốc ức chế MAO trong 2 tuần; viên đêm gây buồn ngủ, không lái xe, không uống rượu.","Hỏi bác sĩ trước khi dùng nếu có bệnh tim, tăng huyết áp, tiểu đường, tuyến giáp, tăng nhãn áp, phì đại tuyến tiền liệt hoặc đang dùng warfarin."]},"74aaf585":{"noi_dau":["Da nhạy cảm, tẩy trang loại khác xong là đỏ rát","Trang điểm cả ngày, tối về mệt chỉ muốn làm sạch thật nhanh","Chai nhỏ dùng mau hết, mua đi mua lại tốn kém"],"cong_dung":["Làm sạch lớp trang điểm và bụi bẩn trên mặt và vùng mắt","Làm dịu, phù hợp da nhạy cảm","Không cần rửa lại bằng nước","Chai 850 ml có vòi nhấn, tiện dùng và tiết kiệm"],"thanh_phan_chinh":"Dung dịch micellar dịu nhẹ dành cho da nhạy cảm","lieu_dung":"Nhấn dung dịch ra bông tẩy trang, lau nhẹ mặt và vùng mắt đến khi bông sạch; không cần rửa lại.","luu_y":["Tránh để dung dịch vào mắt quá nhiều; ngưng dùng nếu kích ứng."]},"229e93e1":{"noi_dau":["Dùng bàn chải điện lâu ngày, lông mòn mà quên thay","Mua đầu thay lẻ từng chiếc vừa đắt vừa phải đi tìm","Răng hay đóng mảng bám dù đánh răng ngày hai lần"],"cong_dung":["Giúp loại bỏ mảng bám nhiều hơn so với bàn chải thường, theo công bố hãng","Lông bàn chải độ cứng vừa, kích thước đầy đủ","Có chip BrushSync nhắc thời điểm thay đầu chải","Lắp vừa mọi tay cầm Philips Sonicare dạng gắn bấm"],"lieu_dung":"Gắn đầu chải vào tay cầm Sonicare, đánh răng như bình thường; thay đầu mới khoảng 3 tháng một lần hoặc khi máy báo. Rửa sạch và để khô sau mỗi lần dùng.","luu_y":["Mỗi người dùng một đầu chải riêng."]},"b67376d9":{"noi_dau":["Sáng ngủ dậy là hắt hơi liên tục, nước mũi chảy không dứt","Giao mùa, phấn hoa, bụi nhà làm mũi nghẹt suốt ngày","Uống thuốc dị ứng hay buồn ngủ, ảnh hưởng công việc"],"cong_dung":["Giảm tạm thời triệu chứng viêm mũi dị ứng và dị ứng hô hấp trên","Giảm nghẹt mũi, sổ mũi, hắt hơi, ngứa mũi","Tác dụng kéo dài 24 giờ, không gây buồn ngủ","Không mùi, không cồn"],"thanh_phan_chinh":"Triamcinolone acetonide 55 mcg mỗi lần xịt (corticoid dạng xịt mũi)","lieu_dung":"Người lớn và trẻ từ 12 tuổi: ngày 1 lần, xịt 2 lần vào mỗi bên mũi; khi đỡ triệu chứng giảm còn 1 lần mỗi bên. Trẻ 6 đến dưới 12 tuổi: ngày 1 lần, 1 xịt mỗi bên (tối đa 2 xịt mỗi bên nếu chưa đỡ), có người lớn giám sát. Trẻ 2 đến dưới 6 tuổi: ngày 1 lần, 1 xịt mỗi bên. Không dùng cho trẻ dưới 2 tuổi.","luu_y":["Trẻ em dùng lâu có thể chậm tăng trưởng; hỏi bác sĩ nếu trẻ cần dùng quá 2 tháng mỗi năm.","Không dùng cho trẻ dưới 2 tuổi; ngưng dùng và hỏi bác sĩ nếu chảy máu mũi, đau mũi, nhìn mờ hoặc triệu chứng không đỡ sau 1 tuần."]},"3eb32309":{"noi_dau":["Đến kỳ là ngực căng tức, tâm trạng thất thường","Bước sang tuổi tiền mãn kinh, cơ thể nhiều thay đổi khó chịu","Da khô ráp, muốn chăm từ bên trong thay vì chỉ bôi kem"],"cong_dung":["Bổ sung dầu hoa anh thảo ép lạnh hàm lượng cao, nguồn GLA tự nhiên","Hỗ trợ sức khỏe phụ nữ trong chu kỳ hằng tháng","Góp phần hỗ trợ làn da khỏe và đủ ẩm","Viên nang mềm giải phóng nhanh, dòng Premium"],"thanh_phan_chinh":"Dầu hoa anh thảo 1300 mg/viên (nguồn axit gamma-linolenic GLA)","lieu_dung":"Người lớn uống 1 viên mỗi ngày, nên uống cùng bữa ăn, hoặc theo hướng dẫn trên nhãn.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc, nhất là thuốc chống đông, nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"1efa5f8c":{"noi_dau":["Uống cà phê, trà mỗi ngày, răng ngả màu dần","Muốn kem đánh răng thành phần tự nhiên cho cả nhà","Răng hay bám mảng bám dù chải đều đặn"],"cong_dung":["Giúp giảm mảng bám và làm sạch răng","Giúp làm trắng răng tự nhiên bằng cách loại bỏ vết ố bề mặt","Hơi thở thơm mát","Thương hiệu theo đuổi thành phần tự nhiên, không thử nghiệm trên động vật"],"lieu_dung":"Chải răng kỹ ít nhất 2 lần mỗi ngày, tốt nhất sau bữa ăn. Trẻ dưới 6 tuổi dùng lượng nhỏ và có người lớn giám sát.","luu_y":["Để xa tầm tay trẻ nhỏ, không nuốt kem đánh răng."]},"e27618bc":{"noi_dau":["Cạo râu buổi sáng vội, hay bị xước và rát da","Lưỡi dao nhanh cùn, phải mua thay liên tục","Mua lẻ từng vỉ nhỏ ở cửa hàng vừa đắt vừa nhanh hết"],"cong_dung":["5 lưỡi dao chống ma sát, cạo sát và êm","Dải bôi trơn cải tiến giúp đường cạo mượt hơn","Hộp 16 đầu dao dùng được nhiều tháng","Lắp vừa tay cầm Gillette ProGlide và Fusion5"],"lieu_dung":"Làm ướt mặt, thoa gel hoặc bọt cạo, cạo theo chiều râu mọc; rửa sạch lưỡi dao sau khi dùng và thay đầu mới khi thấy cạo kém êm.","luu_y":["Lưỡi dao sắc, để xa tầm tay trẻ em."]},"5a3f8681":{"noi_dau":["Ngoài 50 tuổi, chồng hay than mệt, làm việc nhanh đuối sức","Bữa ăn không đủ chất, lo thiếu vitamin khi tuổi cao","Mua nhiều loại vitamin lẻ, uống nhiều viên mỗi ngày dễ quên"],"cong_dung":["Bổ sung vitamin và khoáng chất dành riêng cho nam từ 50 tuổi","Hỗ trợ sức khỏe tim, mắt và chức năng não","Góp phần hỗ trợ chuyển hóa năng lượng và hệ miễn dịch","Hỗ trợ duy trì huyết áp khỏe mạnh theo công bố trên nhãn"],"lieu_dung":"Người lớn nam uống 1 viên mỗi ngày, cùng bữa ăn.","luu_y":["Người đang dùng thuốc, nhất là thuốc chống đông, nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"4aa9827b":{"noi_dau":["Đau đầu, nhức mỏi cả người nên trằn trọc không ngủ được","Cuối ngày làm việc căng thẳng, cơn đau làm mất giấc","Cần loại giảm đau dùng buổi tối, giúp ngủ yên hơn"],"cong_dung":["Giảm tạm thời đau đầu và đau nhức nhẹ kèm khó ngủ","Hỗ trợ giấc ngủ ban đêm nhờ diphenhydramine, không gây lệ thuộc","Viên nang giải phóng nhanh, không chứa aspirin","Cùng hoạt chất với Extra Strength Tylenol PM"],"thanh_phan_chinh":"Acetaminophen 500 mg và Diphenhydramine HCl 25 mg mỗi viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 2 viên trước khi ngủ; không dùng quá 2 viên trong 24 giờ. Không dùng cho trẻ dưới 12 tuổi.","luu_y":["Có acetaminophen: không dùng cùng thuốc khác chứa acetaminophen (paracetamol); quá liều hoặc uống từ 3 ly rượu mỗi ngày có thể gây tổn thương gan nặng.","Không dùng cùng thuốc khác có diphenhydramine, kể cả loại bôi ngoài da; gây buồn ngủ, không lái xe, không uống rượu.","Hỏi bác sĩ trước khi dùng nếu có bệnh gan, tăng nhãn áp, bệnh hô hấp, phì đại tuyến tiền liệt, đang dùng warfarin hoặc đang mang thai, cho con bú."]},"deb18386":{"noi_dau":["Thích uống cà phê, trà ngọt nhưng đang phải hạn chế đường","Trong nhà có người cần kiểm soát đường huyết, nấu nướng phải tính toán","Đường ăn kiêng mua lẻ đắt, dùng mấy hôm đã hết"],"cong_dung":["Tạo vị ngọt giống đường mà gần như không có calo","Gói nhỏ tiện pha cà phê, trà, sữa, sinh tố","Phù hợp người đang kiểm soát lượng đường ăn vào","Hộp lớn 1000 gói, dùng lâu cho cả gia đình"],"thanh_phan_chinh":"Sucralose (chất tạo ngọt), dextrose, maltodextrin","lieu_dung":"Dùng thay đường: mỗi gói cho độ ngọt tương đương khoảng 2 thìa cà phê đường, cho trực tiếp vào đồ uống hoặc món ăn. Bảo quản nơi khô ráo, thoáng mát.","luu_y":["Người bệnh tiểu đường vẫn nên theo chế độ ăn do bác sĩ hướng dẫn."]},"be74d6f0":{"noi_dau":["Mỗi lần chải đầu lại thấy tóc rụng nhiều hơn trước","Sau sinh, tóc thưa mỏng hẳn, buộc lên thấy lộ da đầu","Tóc khô yếu, muốn chăm từ bên trong ngoài dầu gội"],"cong_dung":["Bổ sung biotin hàm lượng cao cho tóc","Hỗ trợ tóc mọc dày và khỏe hơn theo công bố trên nhãn","Kết hợp L-Arginine và silic hỗ trợ dưỡng tóc","Mỗi ngày chỉ 1 viên, lọ 90 viên dùng 3 tháng"],"thanh_phan_chinh":"Biotin 5000 mcg, L-Arginine 500 mg, Silic 10 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày, tốt nhất cùng bữa ăn; dùng đều đặn để thấy hiệu quả.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Biotin liều cao có thể làm sai lệch một số kết quả xét nghiệm máu, hãy báo bác sĩ khi đi xét nghiệm."]},"ce4a0e4f":{"noi_dau":["Ngủ đủ giấc mà sáng dậy người vẫn uể oải, thiếu sức.","Công việc dồn dập, ăn uống vội vàng nên lo thiếu vitamin nhóm B.","Muốn bổ sung cho cả nhà mà ngại uống nhiều loại viên khác nhau."],"cong_dung":["Bổ sung đủ 8 loại vitamin nhóm B thiết yếu trong một viên.","Góp phần hỗ trợ chuyển hoá thức ăn thành năng lượng cho tế bào.","Có thêm vitamin C hỗ trợ hệ miễn dịch.","Hộp lớn 460 viên dùng được lâu, tiện cho gia đình."],"thanh_phan_chinh":"Phức hợp 8 vitamin nhóm B (gồm B1, B2, B3, B6, B12, axit folic, biotin, B5) kèm vitamin C.","lieu_dung":"Người lớn uống 1 viên mỗi ngày với nước, cùng bữa ăn.","luu_y":["Người đang dùng thuốc, đặc biệt thuốc chống co giật, nên hỏi ý kiến bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"5621b014":{"noi_dau":["Đau đầu, đau răng ập đến giữa giờ làm mà không có sẵn thuốc.","Con sốt, chồng đau lưng, nhà cần một hộp thuốc giảm đau tin cậy.","Mua vỉ nhỏ lẻ tẻ, lúc cần lại hết đúng lúc."],"cong_dung":["Giảm tạm thời các cơn đau nhẹ: đau đầu, đau răng, đau lưng, đau cơ.","Giảm đau bụng kinh, đau nhức do cảm cúm thông thường và viêm khớp nhẹ.","Hạ sốt tạm thời.","Hoạt chất ibuprofen 200 mg thuộc nhóm thuốc kháng viêm không steroid (NSAID)."],"thanh_phan_chinh":"Ibuprofen 200 mg/viên.","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi 4–6 giờ khi còn triệu chứng, nếu không đỡ có thể uống 2 viên; không quá 6 viên trong 24 giờ trừ khi bác sĩ chỉ định. Trẻ dưới 12 tuổi: hỏi ý kiến bác sĩ.","luu_y":["Có thể gây xuất huyết dạ dày, nguy cơ cao hơn ở người trên 60 tuổi, có tiền sử loét dạ dày, uống rượu hoặc đang dùng thuốc chống đông.","Không dùng ngay trước hoặc sau phẫu thuật tim; người bệnh tim, huyết áp, thận nên hỏi bác sĩ trước.","Phụ nữ có thai, nhất là 3 tháng cuối, không tự ý dùng; dùng ít nhất có thể, không dùng quá 10 ngày giảm đau hoặc 3 ngày hạ sốt nếu không có chỉ định."]},"3c74629d":{"noi_dau":["Mới ngoài ba mươi mà tóc bạc đã lấm tấm hai bên thái dương.","Nhuộm tóc liên tục vừa tốn kém vừa lo hại da đầu.","Tóc khô, dễ gãy, soi gương thấy mình già hơn tuổi."],"cong_dung":["Bổ sung vitamin nhóm B, khoáng chất và thảo dược cho mái tóc.","Hỗ trợ giảm tình trạng tóc bạc theo công bố của hãng.","Góp phần nuôi dưỡng tóc chắc khoẻ."],"lieu_dung":"Uống 2 viên mỗi ngày (theo thông tin mô tả sản phẩm tìm được, nên đối chiếu lại nhãn trên lọ khi nhận hàng).","luu_y":["Phụ nữ có thai, cho con bú hoặc người đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng.","Hiệu quả tuỳ cơ địa; sản phẩm này không phải là thuốc."]},"2b1fae63":{"noi_dau":["Con kén ăn, bữa nào cũng dỗ mãi mới chịu ăn vài miếng.","Lo con thiếu vitamin vì rau xanh con nhất định không đụng tới.","Cho con uống vitamin dạng siro thì con nhăn mặt, nhè ra."],"cong_dung":["Bổ sung vitamin và khoáng chất tổng hợp hằng ngày cho trẻ.","Hỗ trợ sức khoẻ, sự phát triển và hệ miễn dịch của trẻ.","Dạng kẹo gấu nhiều vị trái cây, trẻ dễ hợp tác.","Hộp lớn 300 viên dùng được lâu cho gia đình có nhiều con nhỏ."],"thanh_phan_chinh":"Vitamin A, C, D, E, B6, B12, axit folic, biotin, kẽm, iốt… dạng kẹo dẻo.","lieu_dung":"Trẻ 2–3 tuổi: 1 viên kẹo mỗi ngày; trẻ từ 4 tuổi trở lên: 2 viên kẹo mỗi ngày. Cho trẻ nhai kỹ.","luu_y":["Không dùng cho trẻ dưới 2 tuổi vì nguy cơ hóc.","Bố mẹ giữ lọ và chia kẹo cho con, để xa tầm tay trẻ vì trẻ dễ ăn quá liều.","Trẻ có bệnh lý hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng."]},"e66032a3":{"noi_dau":["Con không chịu uống nước lọc, cứ đòi nước ngọt đóng chai.","Vắt cam mỗi ngày mất thời gian, cam lại lúc ngọt lúc chua.","Khách đến chơi bất ngờ, muốn có ngay một bình nước mát mời."],"cong_dung":["Pha nhanh một bình nước vị cam thơm mát cho cả nhà.","Bổ sung vitamin C và canxi theo công bố trên bao bì.","Hũ 566 g pha được khoảng 6 quart (gần 5,7 lít) nước.","Tiện mang đi dã ngoại, văn phòng, tiệc gia đình."],"thanh_phan_chinh":"Bột pha đồ uống vị cam, bổ sung vitamin C và canxi.","lieu_dung":"Pha bột với nước lạnh theo tỷ lệ in trên nắp hũ, khuấy đều; dùng ngay hoặc để tủ lạnh. Đậy kín nắp, bảo quản nơi khô mát sau khi mở.","luu_y":["Có đường, nên dùng điều độ, nhất là trẻ nhỏ và người cần kiểm soát đường huyết."]},"24501ea6":{"noi_dau":["Tắm cho con là một trận chiến, gội đầu xong con khóc vì cay mắt.","Tóc con rối bết, chải mỗi sáng là con kêu đau.","Phòng tắm bày đủ chai gội, chai xả, chai tắm cho con."],"cong_dung":["Một chai 3 trong 1: gội, xả và tắm cho bé.","Công thức không cay mắt (tear free), đã kiểm nghiệm da liễu.","Giúp tóc mềm, dễ chải, giảm rối.","Không paraben, hương táo dịu nhẹ trẻ thích."],"lieu_dung":"Làm ướt tóc và người bé, bơm một lượng vừa đủ, xoa tạo bọt trên tóc và cơ thể rồi xả sạch với nước.","luu_y":["Chỉ dùng ngoài da; nếu dính vào mắt thì rửa sạch bằng nước.","Ngưng dùng nếu da bé bị kích ứng."]},"2d7b9fde":{"noi_dau":["Mũi nghẹt suốt đêm, phải thở bằng miệng nên sáng dậy khô họng.","Cứ giao mùa là hắt hơi, sổ mũi vì dị ứng thời tiết.","Ngại dùng thuốc xịt co mạch lâu ngày vì sợ lờn thuốc."],"cong_dung":["Rửa sạch khoang mũi bằng dung dịch muối đẳng trương, không chứa thuốc.","Hỗ trợ giảm triệu chứng mũi do cảm cúm, nghẹt mũi, dị ứng mũi.","Bộ gồm 250 gói muối pha sẵn, 2 bình xịt rửa 240 ml và chai xịt NasaMist 75 ml.","Một bộ dùng được lâu cho cả gia đình."],"thanh_phan_chinh":"Mỗi gói: natri clorid và natri bicarbonat (muối pha sẵn, không chứa thuốc).","lieu_dung":"Pha 1 gói với 240 ml nước cất, nước đã đun sôi để nguội ấm hoặc nước lọc vô khuẩn trong bình, lắc tan; cúi người trên bồn rửa, bóp nhẹ cho dung dịch chảy qua từng bên mũi rồi xì mũi nhẹ. Có thể dùng 1–2 lần mỗi ngày hoặc theo hướng dẫn của bác sĩ.","luu_y":["Không dùng nước máy chưa đun sôi để pha.","Rửa sạch và để khô bình sau mỗi lần dùng, mỗi người dùng một bình riêng.","Nếu mũi tắc hoàn toàn, đau tai hoặc đang viêm tai thì hỏi bác sĩ trước khi rửa."]},"3a8b6889":{"noi_dau":["Đau lưng, đau đầu âm ỉ khiến cả đêm trằn trọc không ngủ được.","Nằm xuống là cơn nhức lại kéo đến, sáng dậy mệt rã rời.","Muốn một viên vừa giảm đau vừa dễ ngủ cho những đêm khó chịu."],"cong_dung":["Giảm tạm thời các cơn đau nhẹ kèm mất ngủ thỉnh thoảng.","Acetaminophen giảm đau, diphenhydramine hỗ trợ dễ ngủ vào ban đêm.","Không gây nghiện theo công bố trên nhãn.","Hộp lớn 225 viên tiện để sẵn trong tủ thuốc gia đình."],"thanh_phan_chinh":"Acetaminophen 500 mg + Diphenhydramine HCl 25 mg/viên.","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 2 viên trước khi đi ngủ; không quá 2 viên trong 24 giờ. Trẻ dưới 12 tuổi: không dùng.","luu_y":["Có thể gây tổn thương gan nghiêm trọng nếu dùng quá 4.000 mg acetaminophen/24 giờ, dùng chung thuốc khác có acetaminophen hoặc uống từ 3 ly rượu mỗi ngày.","Gây buồn ngủ: không lái xe, vận hành máy móc, tránh rượu; không dùng chung sản phẩm khác có diphenhydramine.","Người tăng nhãn áp, bệnh hô hấp mạn, phì đại tiền liệt tuyến, phụ nữ có thai hoặc cho con bú nên hỏi bác sĩ trước khi dùng."]},"7b8d2eae":{"noi_dau":["Lên xuống cầu thang đầu gối kêu lục cục, mỏi rã.","Ngồi lâu đứng dậy khớp cứng, phải xoa bóp một lúc mới đi được.","Thương bố mẹ tuổi cao, đi lại ngày càng chậm và ngại vận động."],"cong_dung":["Bổ sung glucosamine và MSM cho khớp.","Hỗ trợ nâng đỡ khớp và vận động linh hoạt.","Góp phần duy trì sụn khớp khoẻ mạnh.","Hộp 375 viên, dùng 2 viên/ngày được khoảng 6 tháng."],"thanh_phan_chinh":"Glucosamine HCl 1500 mg + MSM 1500 mg trong mỗi liều 2 viên.","lieu_dung":"Người lớn uống 2 viên mỗi ngày, cùng bữa ăn.","luu_y":["Glucosamine có nguồn gốc từ vỏ giáp xác: người dị ứng tôm, cua không nên dùng.","Phụ nữ có thai, cho con bú, người đang dùng thuốc chống đông hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"64bff48c":{"noi_dau":["Ăn tiệc no say xong bụng cồn cào, ợ nóng cả buổi tối.","Đi du lịch đổi món, bụng dạ lục đục làm mất vui cả chuyến.","Đêm buồn nôn, khó tiêu mà không biết lấy gì cho nhẹ bụng."],"cong_dung":["Giảm 5 triệu chứng: buồn nôn, ợ nóng, khó tiêu, đầy khó chịu dạ dày, tiêu chảy.","Công thức Ultra đậm đặc gấp đôi, liều 15 ml tương đương 30 ml loại thường.","Hoạt chất bismuth subsalicylate quen thuộc trong tủ thuốc gia đình Mỹ."],"thanh_phan_chinh":"Bismuth subsalicylate (dạng đậm đặc gấp đôi).","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 15 ml mỗi 30 phút khi cần; riêng tiêu chảy có thể uống 15 ml mỗi 30 phút hoặc 30 ml mỗi giờ. Không quá 8 liều (120 ml) trong 24 giờ, dùng cho tiêu chảy không quá 2 ngày. Trẻ dưới 12 tuổi: hỏi bác sĩ. Lắc kỹ, dùng đúng cốc đong kèm theo.","luu_y":["Trẻ em, thanh thiếu niên đang hoặc vừa khỏi thuỷ đậu, triệu chứng cúm không được dùng vì nguy cơ hội chứng Reye.","Có chứa salicylate: người dị ứng aspirin, đang dùng thuốc chống đông, thuốc tiểu đường, thuốc gout hoặc viêm khớp nên hỏi bác sĩ trước.","Có thể làm lưỡi hoặc phân sẫm màu tạm thời, không gây hại."]},"1d5e1bbe":{"noi_dau":["Sáng nào thức dậy cũng hắt hơi liên tục, nước mũi chảy ròng.","Mắt ngứa, chảy nước mỗi khi trời trở gió hay dọn nhà bụi.","Ngại uống thuốc dị ứng vì sợ buồn ngủ cả ngày làm việc."],"cong_dung":["Giảm tạm thời triệu chứng dị ứng đường hô hấp trên và viêm mũi dị ứng.","Giảm hắt hơi, sổ mũi, ngứa chảy nước mắt, ngứa mũi họng.","Tác dụng kéo dài 24 giờ, chỉ cần 1 viên mỗi ngày.","Dùng được cho dị ứng trong nhà lẫn ngoài trời."],"thanh_phan_chinh":"Cetirizine HCl 10 mg/viên.","lieu_dung":"Người lớn và trẻ từ 6 tuổi đến dưới 65 tuổi: 1 viên mỗi ngày, không quá 1 viên trong 24 giờ. Người từ 65 tuổi, trẻ dưới 6 tuổi, người bệnh gan hoặc thận: hỏi bác sĩ.","luu_y":["Có thể gây buồn ngủ: tránh rượu, thuốc an thần; cẩn trọng khi lái xe, vận hành máy móc.","Không dùng nếu dị ứng cetirizine hoặc hydroxyzine.","Phụ nữ có thai hoặc cho con bú nên hỏi bác sĩ trước khi dùng."]},"c4768ba5":{"noi_dau":["Đứng bán hàng cả ngày, tối về chân nặng trĩu, sưng mắt cá.","Nhìn thấy gân xanh nổi ở bắp chân nên ngại mặc váy.","Đêm nằm chân mỏi, bứt rứt, khó ngủ yên giấc."],"cong_dung":["Hỗ trợ giảm triệu chứng suy giãn tĩnh mạch nhẹ.","Hỗ trợ giảm cảm giác đau, sưng, nặng, mỏi chân do giãn tĩnh mạch nhẹ.","Góp phần hỗ trợ sức bền mao mạch và mạch máu.","Kết hợp hạt dẻ ngựa, hạt nho, cây đậu chổi, hesperidin và vitamin C."],"thanh_phan_chinh":"Chiết xuất hạt dẻ ngựa 166,67 mg (31,67 mg escin), hạt nho, butcher's broom 220 mg, hesperidin 300 mg, vitamin C 200 mg mỗi viên.","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn (sau bữa sáng), hoặc theo hướng dẫn của chuyên gia y tế.","luu_y":["Không khuyến cáo cho phụ nữ có thai hoặc cho con bú.","Uống cách các thuốc khác ít nhất 2 giờ; người đang dùng thuốc hoặc có bệnh lý nên hỏi ý kiến chuyên gia y tế."]},"df78f359":{"noi_dau":["Nghẹt mũi về đêm, trở mình mãi vẫn không thở thông được.","Ngáy to khiến người nằm cạnh mất ngủ theo.","Không muốn dùng thuốc chỉ vì nghẹt mũi lúc đi ngủ."],"cong_dung":["Mở rộng đường thở qua mũi tức thì, không chứa thuốc.","Giảm nghẹt mũi do dị ứng, cảm lạnh hoặc lệch vách ngăn.","Giảm tiếng ngáy do nghẹt mũi, giúp ngủ ngon hơn.","Loại Extra Strength có lực nâng mạnh nhất của hãng."],"thanh_phan_chinh":"Miếng dán cơ học có thanh đàn hồi, không chứa thuốc.","lieu_dung":"Rửa sạch và lau khô sống mũi, bóc lớp lót, đặt miếng dán lên sống mũi rồi miết nhẹ hai đầu cho dính. Mỗi miếng dùng một lần, có thể dùng hằng ngày nhưng không quá 12 giờ mỗi ngày.","luu_y":["Không dùng cho trẻ dưới 5 tuổi; không dán lên da đang trầy xước, cháy nắng hoặc kích ứng.","Bao bì có chứa latex cao su tự nhiên, có thể gây dị ứng; ngưng dùng nếu nổi mẩn.","Không dùng để điều trị ngưng thở khi ngủ."]},"2fbfe33e":{"noi_dau":["Đánh răng kỹ mà mảng bám vẫn còn, cạo vôi mãi không hết.","Đánh mạnh tay quá làm chảy máu chân răng, ê buốt.","Đi công tác mang bàn chải điện bất tiện vì không có hộp đựng."],"cong_dung":["Đầu chải tròn chuyển động xoay, làm sạch từng chiếc răng.","Có đèn cảnh báo khi chải quá mạnh, giúp bảo vệ nướu.","Hẹn giờ giúp chải đủ thời gian khuyến nghị.","Bộ đôi tiện cho hai người, kèm hộp du lịch và đế sạc riêng."],"lieu_dung":"Sạc đầy trước khi dùng; đặt đầu chải nghiêng vào viền nướu, lướt chậm từ răng này sang răng khác, không cần chà mạnh. Thay đầu chải khoảng 3 tháng một lần, rửa sạch đầu chải sau mỗi lần dùng.","luu_y":["Đế sạc dùng điện 110–120V của Mỹ: cần bộ đổi nguồn phù hợp khi dùng ở Việt Nam.","Trẻ em dùng cần có người lớn giám sát; không dùng đế sạc bị hỏng dây."]},"514d4ee0":{"noi_dau":["Ăn thịt xong thức ăn giắt kẽ răng, xỉa tăm gỗ lại chảy máu.","Dùng chỉ nha khoa lóng ngóng, mất thời gian mỗi tối.","Niềng răng, làm cầu răng nên vệ sinh kẽ răng rất khó."],"cong_dung":["Lông cao su mềm làm sạch thức ăn và mảng bám ở kẽ răng.","Tay cầm dài, cong và đầu thon giúp với tới răng trong sâu dễ dàng.","Phù hợp kẽ răng nhỏ, người niềng răng, làm cầu răng hoặc implant.","Kèm hộp nhỏ tiện mang theo khi đi làm, đi chơi."],"lieu_dung":"Nhúng ướt đầu tăm, đưa nhẹ nhàng vào kẽ răng và kéo ra vào vài lần, không ấn mạnh. Dùng sau bữa ăn hoặc trước khi đánh răng, rửa sạch sau khi dùng.","luu_y":["Không cố ấn vào kẽ răng quá hẹp để tránh tổn thương nướu.","Để xa tầm tay trẻ nhỏ."]},"a906aa1d":{"noi_dau":["Rửa bát, giặt giũ nhiều nên tay khô ráp, nứt nẻ đầu ngón.","Gót chân chai sạn, nứt nẻ, ngại đi dép hở.","Bôi kem dưỡng thì nhờn dính, cầm điện thoại cũng khó chịu."],"cong_dung":["Kem tay và body sữa dê không mùi, dưỡng ẩm sâu, không nhờn dính.","Sữa dê giàu vitamin và khoáng tự nhiên, làm dịu và nuôi dưỡng da khô.","Kem Sole Keeper chăm sóc gót chân chai sần, nứt nẻ.","Giúp khử mùi, làm dịu và mát chân, làm mềm da gót.","Không paraben, không thử nghiệm trên động vật."],"thanh_phan_chinh":"Sữa dê; tuýp kem tay 3,3 oz (93 g) và tuýp kem chân 4 oz (113 g).","lieu_dung":"Kem tay: thoa lên tay và vùng da khô bất cứ khi nào cần. Kem chân: thoa đều lên gót và lòng bàn chân sạch, khô, tốt nhất vào buổi tối trước khi ngủ.","luu_y":["Chỉ dùng ngoài da, tránh vùng mắt; ngưng dùng nếu kích ứng."]},"847cca34":{"noi_dau":["Thịt cá cấp đông vài tuần đã bị cháy lạnh, mất ngon.","Tủ lạnh chật kín hộp to hộp nhỏ, đồ ăn dễ ám mùi nhau.","Mua đồ khô số lượng lớn cho rẻ nhưng mở ra để lâu dễ ẩm mốc."],"cong_dung":["5 chế độ: Sous Vide, Pulse, Dry, Moist và Marinate (ướp nhanh).","Có ống hút cầm tay để hút hộp và túi zip dùng cho tủ mát, tủ đồ khô.","Ngăn chứa cuộn túi và dao cắt tích hợp, tự cắt túi theo kích cỡ.","Khay hứng nước rời, dễ tháo rửa.","Kèm cuộn túi 28 cm x 2,4 m và một số túi hút chân không."],"lieu_dung":"Cho thực phẩm vào túi, để chừa mép, đặt miệng túi vào khe hút, chọn chế độ Dry hoặc Moist rồi nhấn hút và hàn. Lau khô thực phẩm ướt trước khi hút, đổ nước khay hứng sau khi dùng.","luu_y":["Máy dùng điện 120V của Mỹ: bắt buộc dùng bộ đổi nguồn 220V sang 110V đủ công suất.","Hút chân không không thay thế bảo quản lạnh: thực phẩm tươi vẫn phải để tủ lạnh hoặc tủ đông."]},"72490ba2":{"noi_dau":["Mấy ngày chưa đi vệ sinh, bụng căng tức, khó chịu.","Đi xa, đổi chỗ ở là bụng dạ lại tắc nghẽn.","Ăn rau, uống nước nhiều mà thỉnh thoảng vẫn bị táo bón."],"cong_dung":["Giảm táo bón thỉnh thoảng (không thường xuyên).","Thường có tác dụng sau 6–12 giờ, uống buổi tối để sáng hôm sau dễ đi.","Viên bao giúp thuốc tác động tại ruột già."],"thanh_phan_chinh":"Bisacodyl 5 mg/viên (thuốc nhuận tràng kích thích).","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1–3 viên (thường là 2 viên) một lần trong ngày. Trẻ 6 đến dưới 12 tuổi: 1 viên một lần trong ngày. Trẻ dưới 6 tuổi: hỏi bác sĩ. Nuốt nguyên viên với nước, không nhai, không bẻ.","luu_y":["Không uống trong vòng 1 giờ sau khi dùng thuốc kháng axit hoặc uống sữa.","Không dùng quá 7 ngày nếu không có chỉ định; không dùng khi đau bụng, buồn nôn hoặc nôn.","Ngưng dùng và hỏi bác sĩ nếu chảy máu trực tràng hoặc không đi ngoài được sau khi dùng."]},"eea44e25":{"noi_dau":["Ngồi phòng máy lạnh cả ngày, môi khô bong tróc.","Thoa son lì lâu ngày môi thâm, nứt nẻ.","Muốn môi hồng tự nhiên mà không cần đánh son."],"cong_dung":["Dưỡng ẩm, làm mềm môi khô nứt nẻ.","Cho đôi môi ánh hồng nhẹ tự nhiên.","Có thể dùng làm lớp lót trước khi tô son.","Hũ nhỏ 7 g gọn trong túi xách."],"thanh_phan_chinh":"Sáp dầu khoáng tinh khiết (petroleum jelly) có màu hồng nhẹ.","lieu_dung":"Thoa một lớp mỏng lên môi bất cứ khi nào thấy khô, có thể dùng trước khi ngủ hoặc làm lớp nền trước son.","luu_y":["Chỉ dùng ngoài; ngưng dùng nếu môi kích ứng."]},"720c5270":{"noi_dau":["Cạo dao lam xong mặt rát đỏ, lấm tấm vết xước.","Râu mọc nhanh, sáng nào cũng vội vàng cạo cho kịp giờ làm.","Chọn quà cho chồng, bố mà không biết mua gì cho thiết thực."],"cong_dung":["Lưỡi cạo có lớp phủ chống ma sát, giảm kích ứng da.","Cạo được cả khô lẫn ướt, dùng với gel hoặc bọt cạo.","Kèm đầu tỉa chính xác để chỉnh ria mép, tóc mai.","Dùng pin sạc, không cần cắm dây khi cạo; kèm túi đựng tiện mang đi."],"lieu_dung":"Sạc đầy trước khi dùng; đặt đầu cạo áp sát da, di chuyển theo vòng tròn nhỏ. Sau khi dùng mở đầu cạo, xả nước sạch và để khô.","luu_y":["Đế sạc dùng điện 110–120V của Mỹ: cần bộ đổi nguồn phù hợp khi dùng ở Việt Nam (trừ khi bộ sạc ghi 100–240V).","Không dùng khi đầu cạo hoặc lưới cạo bị hỏng để tránh xước da."]},"7c7ef58d":{"noi_dau":["Nằm trằn trọc đến nửa đêm mà mắt vẫn mở thao láo.","Đổi múi giờ sau chuyến bay, đêm thức ngày buồn ngủ.","Thỉnh thoảng lo nghĩ nhiều nên khó vào giấc."],"cong_dung":["Giúp giảm khó vào giấc ngủ (mất ngủ thỉnh thoảng).","Chỉ 1 viên mỗi liều.","Cùng hoạt chất với Unisom SleepTabs.","Hộp 2 lọ, mỗi lọ 96 viên."],"thanh_phan_chinh":"Doxylamine succinate 25 mg/viên.","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên trước khi đi ngủ 30 phút, mỗi ngày 1 lần hoặc theo chỉ dẫn của bác sĩ. Trẻ dưới 12 tuổi: không dùng.","luu_y":["Chỉ uống khi ngủ được trọn đêm; không lái xe, vận hành máy móc, tránh rượu khi dùng.","Người bệnh hô hấp mạn tính, tăng nhãn áp, tiểu khó do phì đại tiền liệt tuyến, phụ nữ có thai hoặc cho con bú nên hỏi bác sĩ trước.","Mất ngủ kéo dài liên tục quá 2 tuần cần đi khám vì có thể do bệnh lý khác."]},"3284e146":{"noi_dau":["Quần áo phơi trong nhà mùa nồm cứ có mùi ẩm khó chịu.","Giặt xong thơm được một buổi, mặc đến chiều đã hết mùi.","Đồ thể thao của chồng con giặt mãi vẫn còn mùi mồ hôi."],"cong_dung":["Hạt tăng hương cho vào máy giặt, giữ quần áo thơm lâu.","Mùi Fresh tươi mát, dùng kèm nước giặt và nước xả quen thuộc.","Tuỳ chỉnh lượng hạt để mùi đậm hay nhẹ theo ý thích.","Hũ lớn 1,06 kg dùng được nhiều mẻ giặt."],"lieu_dung":"Lắc hạt vào nắp, đổ trực tiếp vào lồng giặt trước khi cho quần áo vào; không đổ vào ngăn chứa nước giặt hay nước xả. Đậy kín nắp, để nơi khô ráo.","luu_y":["Để xa tầm tay trẻ em và thú cưng; nếu nuốt phải hoặc dính mắt, rửa sạch bằng nước và hỏi ý kiến bác sĩ.","Không dùng cho đồ chống cháy hoặc đồ cần giặt tay theo hướng dẫn trên nhãn quần áo."]},"fd5872ad":{"noi_dau":["Mặc áo đen thì sợ vệt trắng, áo sáng màu lại sợ ố vàng.","Trời nóng, chạy việc cả ngày, lo mùi cơ thể khi gặp khách.","Dùng lăn khử mùi xong vùng da dưới cánh tay khô rát."],"cong_dung":["Ngăn mồ hôi và mùi cơ thể đến 48 giờ.","Không để vệt trắng trên 100 màu vải.","Công thức 1/4 kem dưỡng ẩm, dịu nhẹ với da dưới cánh tay.","Hương dưa leo và nước xương rồng tươi mát."],"thanh_phan_chinh":"Sáp ngăn mồ hôi chứa muối nhôm, bổ sung 1/4 thành phần dưỡng ẩm.","lieu_dung":"Chỉ dùng cho vùng dưới cánh tay: xoay đẩy sáp lên, thoa một lớp mỏng lên da sạch và khô.","luu_y":["Không dùng trên da trầy xước, ngưng dùng nếu nổi mẩn hoặc kích ứng.","Người bệnh thận nên hỏi bác sĩ trước khi dùng sản phẩm ngăn mồ hôi.","Để xa tầm tay trẻ em."]},"fe665cf4":{"noi_dau":["Ăn đồ cay, uống cà phê xong là nóng rát sau xương ức.","Đêm nằm xuống lại ợ chua, trào ngược làm mất ngủ.","Tiệc tùng cuối năm nhiều, lo bụng không chịu nổi."],"cong_dung":["Giảm ợ nóng do khó tiêu, chua dạ dày.","Phòng ngừa ợ nóng khi uống trước bữa ăn có đồ dễ gây ợ chua.","Liều tối đa không kê đơn, chỉ 1 viên mỗi lần.","Cùng hoạt chất với Pepcid AC Maximum Strength."],"thanh_phan_chinh":"Famotidine 20 mg/viên.","lieu_dung":"Người lớn và trẻ từ 12 tuổi: để giảm triệu chứng, nuốt 1 viên với một cốc nước; để phòng ngừa, uống 1 viên 10–60 phút trước khi ăn hoặc uống thứ dễ gây ợ nóng. Không quá 2 viên trong 24 giờ. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Không dùng liên tục quá 14 ngày nếu không có chỉ định; không dùng chung thuốc giảm axit khác.","Hỏi bác sĩ trước nếu bệnh thận, khó nuốt, nôn ra máu, phân đen, đau ngực hoặc ợ nóng kéo dài trên 3 tháng.","Phụ nữ có thai hoặc cho con bú nên hỏi bác sĩ trước khi dùng."]},"33e8eb79":{"noi_dau":["Ăn tiệc quá đà, sáng hôm sau vừa nhức đầu vừa nóng rát dạ dày.","Đau đầu kèm khó tiêu mà phải uống hai ba loại thuốc.","Ợ chua, đầy bụng làm cả buổi làm việc không tập trung."],"cong_dung":["Giảm ợ nóng, chua dạ dày, khó tiêu do axit.","Giảm khó chịu dạ dày kèm đau đầu hoặc đau nhức cơ thể.","Dạng viên sủi tan trong nước, dễ uống.","Mỗi gói 2 viên tiện mang theo khi đi xa."],"thanh_phan_chinh":"Mỗi viên: aspirin 325 mg, axit citric khan 1000 mg, natri bicarbonat 1916 mg.","lieu_dung":"Hoà tan hoàn toàn 2 viên trong 120 ml nước trước khi uống. Người lớn và trẻ từ 12 tuổi: 2 viên mỗi 4 giờ, không quá 8 viên trong 24 giờ. Người từ 60 tuổi: 2 viên mỗi 4 giờ, không quá 4 viên trong 24 giờ. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Có aspirin: trẻ em, thanh thiếu niên đang hoặc vừa khỏi thuỷ đậu, cúm không được dùng vì nguy cơ hội chứng Reye.","Nguy cơ xuất huyết dạ dày cao hơn ở người từ 60 tuổi, có tiền sử loét, đang dùng thuốc chống đông hoặc uống rượu.","Chứa nhiều natri: người ăn kiêng muối, bệnh tim, huyết áp nên hỏi bác sĩ; phụ nữ có thai 3 tháng cuối không dùng."]},"dd08069e":{"noi_dau":["Bận rộn cả ngày, bữa ăn thiếu hẳn rau xanh và trái cây.","Con lười ăn rau, mẹ nghĩ đủ cách mà con vẫn lắc đầu.","Muốn uống nước ép mỗi ngày nhưng không có thời gian tự ép."],"cong_dung":["Bổ sung bột từ nhiều loại trái cây và rau củ hữu cơ.","Có vitamin C và kẽm góp phần hỗ trợ miễn dịch.","Bổ sung chất xơ prebiotic, lợi khuẩn và enzyme tiêu hoá.","Chứng nhận hữu cơ USDA, thuần chay, không biến đổi gen, không gluten."],"thanh_phan_chinh":"Mỗi muỗng canh: vitamin C 45 mg, kẽm 6,9 mg, chất xơ 3 g; hỗn hợp rau quả hữu cơ, lợi khuẩn, enzyme.","lieu_dung":"Mỗi ngày pha 1 muỗng canh bột với khoảng 240 ml nước hoặc sinh tố, khuấy hoặc lắc đều rồi uống. Đậy kín nắp, bảo quản nơi khô mát.","luu_y":["Phụ nữ có thai, cho con bú hoặc người có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"7f17ea4e":{"noi_dau":["Đang nói dở câu chuyện thì quên mất mình định nói gì","Đọc tài liệu một lúc là mắt mỏi, đầu óc khó tập trung","Việc nhà, việc kinh doanh dồn dập khiến đầu óc lúc nào cũng căng"],"cong_dung":["Hỗ trợ trí nhớ, khả năng tập trung và sự chú ý theo công bố của hãng","Bổ sung đầy đủ vitamin và khoáng chất tổng hợp cho cơ thể mỗi ngày","Kết hợp phức hợp dưỡng chất dành riêng cho não bộ","Phù hợp người lớn bận rộn, cần đầu óc minh mẫn khi làm việc"],"thanh_phan_chinh":"Vitamin – khoáng chất tổng hợp kèm phức hợp dưỡng não độc quyền của hãng","lieu_dung":"Người lớn uống 4 viên mỗi ngày cùng bữa ăn; có thể tăng tối đa 8 viên/ngày tùy thể trạng, mức hoạt động và chế độ ăn.","luu_y":["Phụ nữ có thai, đang cho con bú hoặc người có bệnh lý cần hỏi bác sĩ trước khi dùng.","Sản phẩm này không phải là thuốc và không có tác dụng thay thế thuốc."]},"9f194c86":{"noi_dau":["Bước qua tuổi 50, anh nhà hay than mệt và ngại vận động","Ăn uống thất thường nên lo cơ thể thiếu vi chất mà không biết","Muốn chăm sức khỏe cho chồng, bố mẹ nhưng không biết bắt đầu từ đâu"],"cong_dung":["Bổ sung vitamin và khoáng chất tổng hợp cho nam giới trên 50 tuổi","Hỗ trợ chức năng tim, não, mắt và cơ bắp theo công bố trên nhãn","Góp phần bù đắp vi chất khi chế độ ăn chưa đầy đủ","Mỗi ngày chỉ một viên, dễ duy trì lâu dài"],"thanh_phan_chinh":"Vitamin – khoáng chất tổng hợp công thức riêng cho nam 50+","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn.","luu_y":["Không dùng cho trẻ em; để xa tầm tay trẻ.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi ý kiến bác sĩ trước khi dùng."]},"2a81239c":{"noi_dau":["Nằm trằn trọc cả tiếng đồng hồ mà vẫn chưa chợp mắt được","Nửa đêm tỉnh giấc rồi khó ngủ lại đến sáng","Lệch múi giờ, đổi ca làm khiến giấc ngủ đảo lộn"],"cong_dung":["Bổ sung melatonin giúp hỗ trợ đi vào giấc ngủ nhanh hơn","Hỗ trợ ngủ sâu và lâu hơn theo công bố trên nhãn","Viên tan nhanh trong miệng, không cần uống với nước","Không gây lệ thuộc như thuốc ngủ theo công bố của hãng"],"thanh_phan_chinh":"Melatonin 5 mg/viên","lieu_dung":"Người lớn ngậm 1 viên khoảng 20 phút trước khi đi ngủ, để viên tự tan trong miệng.","luu_y":["Chỉ dành cho người lớn; không dùng cho phụ nữ có thai, cho con bú và người dưới 18 tuổi.","Có thể gây buồn ngủ, không lái xe hay vận hành máy sau khi dùng.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"b7f0f33a":{"noi_dau":["Qua tuổi 40, leo vài bậc cầu thang đã thấy hụt hơi","Lo lắng chuyện tim mạch khi trong nhà có người cao huyết áp","Cơ thể nhanh mệt, thiếu năng lượng dù ăn uống đầy đủ"],"cong_dung":["Bổ sung Coenzyme Q10 hàm lượng cao 300 mg mỗi viên","Hỗ trợ sức khỏe tim mạch theo công bố trên nhãn","Góp phần duy trì huyết áp ở mức khỏe mạnh","Hỗ trợ quá trình tạo năng lượng cho tế bào"],"thanh_phan_chinh":"Coenzyme Q10 300 mg/viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc (nhất là thuốc chống đông) nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"04b79264":{"noi_dau":["Đau đầu, đau răng ập đến đúng lúc đang bận việc","Mỗi tháng đến kỳ lại đau bụng, mỏi lưng khó chịu","Con hay chồng sốt nhẹ, đau mình mẩy sau ngày dài"],"cong_dung":["Giảm tạm thời các cơn đau nhẹ: đau đầu, đau răng, đau lưng, đau cơ","Giảm đau bụng kinh và đau nhức do cảm lạnh thông thường","Giảm đau nhẹ do viêm khớp","Hạ sốt tạm thời"],"thanh_phan_chinh":"Ibuprofen 200 mg/viên (dạng hòa tan)","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi 4–6 giờ khi còn triệu chứng; nếu không đỡ có thể uống 2 viên; không quá 6 viên trong 24 giờ trừ khi bác sĩ chỉ định. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Thuốc chống viêm không steroid có thể gây xuất huyết dạ dày, nguy cơ cao hơn ở người trên 60 tuổi, có tiền sử loét dạ dày, đang dùng thuốc chống đông hoặc uống rượu.","Có thể tăng nguy cơ đau tim, đột quỵ; không dùng ngay trước hoặc sau phẫu thuật tim.","Phụ nữ mang thai từ 20 tuần trở lên phải hỏi bác sĩ; không dùng nếu từng dị ứng với thuốc giảm đau, hạ sốt."]},"6e2d7b7d":{"noi_dau":["Con kén ăn, bữa nào cũng phải dỗ mới chịu ăn vài thìa","Bé lười uống vitamin dạng siro, cứ thấy là lắc đầu","Lo con thiếu vi chất nên chậm lớn hơn các bạn"],"cong_dung":["Bổ sung vitamin và khoáng chất tổng hợp cho trẻ","Hỗ trợ sự tăng trưởng và phát triển khỏe mạnh theo công bố trên nhãn","Dạng kẹo dẻo vị trái cây, bé dễ hợp tác","Hương vị tự nhiên cam, anh đào, táo xanh"],"thanh_phan_chinh":"Vitamin – khoáng chất tổng hợp dạng kẹo dẻo cho trẻ","lieu_dung":"Trẻ 2–3 tuổi: nhai 1 viên mỗi ngày. Người lớn và trẻ từ 4 tuổi: nhai 2 viên mỗi ngày.","luu_y":["Không dùng cho trẻ dưới 2 tuổi; người lớn nên giám sát khi trẻ nhai kẹo.","Cất xa tầm tay trẻ, tránh trẻ tự lấy ăn như kẹo."]},"58fb5e05":{"noi_dau":["Cơn đau đầu kéo dài làm cả buổi làm việc mất tập trung","Người lớn trong nhà sốt, đau mình mẩy khi trở trời","Đau nhức cơ, đau lưng sau một ngày đứng bán hàng"],"cong_dung":["Giảm tạm thời đau nhẹ: đau đầu, đau cơ, đau lưng, đau răng","Giảm đau bụng kinh và đau nhức do cảm lạnh","Giảm đau nhẹ do viêm khớp","Hạ sốt tạm thời"],"thanh_phan_chinh":"Acetaminophen (paracetamol) 500 mg/viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 2 viên mỗi 6 giờ khi còn triệu chứng; không quá 6 viên trong 24 giờ trừ khi bác sĩ chỉ định; không dùng quá 10 ngày. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Cảnh báo gan: có thể gây tổn thương gan nặng nếu dùng quá liều, dùng chung thuốc khác có acetaminophen hoặc uống từ 3 ly rượu mỗi ngày.","Ngưng dùng và hỏi bác sĩ nếu có phản ứng da như đỏ, phồng rộp, phát ban.","Người có bệnh gan hoặc đang dùng thuốc chống đông warfarin phải hỏi bác sĩ trước khi dùng."]},"2042323a":{"noi_dau":["Đau khớp, đau lưng âm ỉ kéo dài cả ngày","Uống thuốc giảm đau vài tiếng lại phải uống tiếp, thấy phiền","Đau bụng kinh khiến mấy ngày đầu tháng chẳng làm được gì"],"cong_dung":["Giảm tạm thời đau nhẹ: đau đầu, đau răng, đau lưng, đau cơ","Giảm đau bụng kinh và đau nhẹ do viêm khớp","Giảm đau nhức do cảm lạnh thông thường","Hạ sốt tạm thời; một liều tác dụng đến 12 giờ theo nhãn"],"thanh_phan_chinh":"Naproxen sodium 220 mg/viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi 8–12 giờ với đầy ly nước; liều đầu có thể uống 2 viên trong giờ đầu; không quá 2 viên trong 8–12 giờ và không quá 3 viên trong 24 giờ. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Thuốc chống viêm không steroid có thể gây xuất huyết dạ dày, nhất là người trên 60 tuổi, có loét dạ dày, đang dùng thuốc chống đông hoặc uống rượu.","Có thể tăng nguy cơ đau tim, đột quỵ; không dùng ngay trước hoặc sau phẫu thuật tim.","Phụ nữ mang thai từ 20 tuần trở lên phải hỏi bác sĩ trước khi dùng."]},"ae39b88e":{"noi_dau":["Làm việc trong nhà cả ngày, hiếm khi được ra nắng","Tuổi trung niên bắt đầu lo xương khớp yếu dần","Trở trời là cả nhà dễ ốm vặt, sổ mũi"],"cong_dung":["Bổ sung vitamin D3 2000 IU mỗi viên","Hỗ trợ sức khỏe xương và hệ miễn dịch theo công bố trên nhãn","Góp phần hấp thu canxi hiệu quả hơn","Hộp 600 viên dùng được lâu cho cả gia đình người lớn"],"thanh_phan_chinh":"Vitamin D3 50 mcg (2000 IU)/viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"572b7488":{"noi_dau":["Hay phải đi tiểu, cảm giác buốt rát khiến ngại uống nước","Ngồi bán hàng cả ngày, nhịn tiểu thành thói quen","Lo lắng vì vấn đề đường tiết niệu cứ lặp lại"],"cong_dung":["Bổ sung chiết xuất nam việt quất Pacran đã được nghiên cứu lâm sàng","Hỗ trợ sức khỏe đường tiết niệu theo công bố trên nhãn","Góp phần chống oxy hóa cho cơ thể","Mỗi ngày chỉ một viên nang chay"],"thanh_phan_chinh":"Nam việt quất Pacran 650 mg (36 mg PACs)/viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày với nước, nên uống cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc (nhất là thuốc chống đông) nên hỏi bác sĩ trước khi dùng.","Nếu nghi ngờ nhiễm trùng tiết niệu, cần đi khám và dùng thuốc theo chỉ định."]},"4a6b4768":{"noi_dau":["Soi gương thấy da xỉn màu, kém tươi hơn trước","Bận con nhỏ, việc nhà nên chẳng có thời gian chăm da","Qua tuổi 35 thấy cơ thể nhanh mệt, thiếu sức sống"],"cong_dung":["Bổ sung tinh chất nhau thai cừu tương đương 5000 mg mỗi viên","Hỗ trợ duy trì vẻ tươi trẻ và sức khỏe tổng quát theo công bố trên nhãn","Thuộc dòng sản phẩm chăm sóc sức khỏe chung của hãng","Không chứa đường, men, gluten, muối, màu và chất bảo quản nhân tạo"],"thanh_phan_chinh":"Nhau thai cừu cô đặc tương đương 5000 mg/viên","lieu_dung":"Người lớn uống 1–3 viên mỗi ngày, hoặc theo hướng dẫn của bác sĩ.","luu_y":["Phụ nữ có thai, đang cho con bú và trẻ dưới 12 tuổi không nên dùng.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"8e52c158":{"noi_dau":["Đau lưng, đau đầu về đêm khiến nằm mãi không ngủ được","Cơn nhức mỏi làm giấc ngủ chập chờn, sáng dậy càng mệt","Ban ngày bận rộn, tối đến cơn đau lại âm ỉ"],"cong_dung":["Giảm tạm thời các cơn đau nhẹ kèm khó ngủ về đêm","Hỗ trợ dễ ngủ khi mất ngủ do đau nhức","Kết hợp thuốc giảm đau ibuprofen và chất hỗ trợ ngủ diphenhydramine","Dạng viên bao phim dễ nuốt"],"thanh_phan_chinh":"Ibuprofen 200 mg + Diphenhydramine citrate 38 mg/viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 2 viên trước khi đi ngủ; không quá 2 viên trong 24 giờ. Không dùng cho trẻ dưới 12 tuổi.","luu_y":["Gây buồn ngủ rõ rệt: tránh rượu, không lái xe hay vận hành máy; không dùng chung sản phẩm khác có diphenhydramine.","Thuốc chống viêm không steroid có thể gây xuất huyết dạ dày và tăng nguy cơ đau tim, đột quỵ.","Người bị tăng nhãn áp, khó tiểu do phì đại tuyến tiền liệt, phụ nữ mang thai từ 20 tuần phải hỏi bác sĩ."]},"c8e15e27":{"noi_dau":["Đi làm về người mệt, chỉ muốn tắm cho thật thư giãn","Nhiều sữa tắm tạo cảm giác nhờn, tắm xong vẫn thấy bí","Mua chai nhỏ dùng vài hôm đã hết, cả nhà dùng tốn kém"],"cong_dung":["Gel tắm làm sạch nhẹ nhàng, cho cảm giác sảng khoái","Hương Original đặc trưng, tạo bọt mịn","Rửa trôi sạch, không để lại cảm giác nhờn rít","Chai lớn 1182 ml có vòi nhấn, tiện cho cả gia đình"],"lieu_dung":"Cho một lượng gel vừa đủ lên da ướt hoặc bông tắm, tạo bọt rồi tắm sạch lại với nước.","luu_y":["Chỉ dùng ngoài da; tránh để dính vào mắt, nếu dính rửa ngay bằng nước sạch."]},"77e530e1":{"noi_dau":["Sáng nào cũng cuống cuồng không biết làm gì cho con ăn sáng","Muốn có món mặn nhanh gọn nhưng ngại ăn quá mặn","Đi du lịch, dã ngoại cần đồ ăn tiện mang theo"],"cong_dung":["Thịt hộp ăn liền, ít natri hơn 25% so với SPAM Classic theo nhãn","Chế biến nhanh: chiên, áp chảo, kẹp bánh mì, cơm nắm, mì","Hộp nắp giật tiện mở, dễ bảo quản","Phù hợp dự trữ trong bếp cho ngày bận rộn"],"lieu_dung":"Mở hộp, cắt lát dùng ngay hoặc áp chảo vàng hai mặt. Phần chưa dùng hết cho vào hộp kín, bảo quản tủ lạnh và dùng sớm.","luu_y":["Không dùng nếu hộp bị phồng, móp sâu hoặc rỉ sét."]},"da52266b":{"noi_dau":["Ga giường mau xù, giặt vài lần đã bạc màu","Ga bọc nông, nằm một đêm là tuột góc nhăn nhúm","Ga cotton nhăn nhiều, phơi xong lại phải là phẳng"],"cong_dung":["Vải microfiber polyester chải mịn, mềm tay","Ít nhăn, bền màu sau nhiều lần giặt","Ga bọc túi sâu khoảng 43 cm, ôm nệm dày tốt","Nhiều họa tiết nhã nhặn, dễ phối phòng ngủ"],"lieu_dung":"Giặt máy nước lạnh, chế độ nhẹ; sấy nhiệt thấp hoặc phơi nơi thoáng. Cỡ Queen ga bọc 152 x 203 cm.","luu_y":[]},"6199666f":{"noi_dau":["Trở gió một chút là cả nhà thay nhau hắt hơi, sổ mũi","Con đi học về hay mang theo cảm cúm lây cả nhà","Bận rộn, thiếu ngủ nên dễ mệt và ốm vặt"],"cong_dung":["Bổ sung vitamin C dạng Ester-C 1000 mg mỗi liều","Kết hợp vitamin D, kẽm, cơm cháy và cúc tím","Hỗ trợ miễn dịch suốt 24 giờ theo công bố của hãng","Hỗ trợ sức khỏe đường hô hấp trên"],"thanh_phan_chinh":"Vitamin C (Ester-C) 1000 mg, vitamin D 15 mcg, kẽm 15 mg mỗi liều 2 viên","lieu_dung":"Người lớn uống 2 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"dec3b606":{"noi_dau":["Ăn xong một lúc là nóng rát sau xương ức","Ăn cay, uống cà phê là lại ợ chua khó chịu","Nằm xuống buổi tối thấy trào ngược, không ngủ yên"],"cong_dung":["Giảm chứng ợ nóng do tăng tiết axit, khó tiêu do axit, đầy bụng chua","Phòng ngừa ợ nóng khi ăn đồ ăn, thức uống dễ gây ợ nóng","Chỉ cần một viên theo công bố trên nhãn"],"thanh_phan_chinh":"Famotidine 20 mg/viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: để giảm triệu chứng uống 1 viên với nước; để phòng ngừa uống 1 viên 10–60 phút trước khi ăn món dễ gây ợ nóng; không quá 2 viên trong 24 giờ. Trẻ dưới 12 tuổi: hỏi bác sĩ.","luu_y":["Không dùng quá 14 ngày liên tục trừ khi bác sĩ chỉ định; không dùng chung thuốc giảm axit khác.","Không dùng nếu khó nuốt, nôn ra máu, phân đen hoặc có máu; người bệnh thận phải hỏi bác sĩ.","Đến bác sĩ ngay nếu đau ngực, đau lan ra tay, cổ, vai kèm khó thở hoặc vã mồ hôi."]},"82c37d7d":{"noi_dau":["Bé ăn kẹo, uống sữa đêm nên mẹ lo sâu răng sớm","Con sợ vị cay của kem đánh răng người lớn, không chịu đánh","Mỗi tối dỗ con đánh răng là cả một cuộc chiến"],"cong_dung":["Kem đánh răng có fluor giúp phòng ngừa sâu răng","Vị Sparkle Fun dịu nhẹ, trẻ dễ chấp nhận","Có dấu chứng nhận của Hiệp hội Nha khoa Hoa Kỳ (ADA) trên vỏ hộp","Tuýp lớn 130 g dùng được lâu"],"thanh_phan_chinh":"Sodium fluoride 0,243% (0,15% ion fluor)","lieu_dung":"Người lớn và trẻ từ 2 tuổi: chải răng kỹ, tốt nhất sau mỗi bữa ăn hoặc ít nhất 2 lần/ngày. Trẻ dưới 6 tuổi dùng lượng bằng hạt đậu và có người lớn giám sát; trẻ dưới 2 tuổi hỏi nha sĩ.","luu_y":["Để xa tầm tay trẻ dưới 6 tuổi; dạy trẻ nhổ ra, không nuốt.","Nếu lỡ nuốt nhiều hơn lượng dùng để chải răng, đưa trẻ đến cơ sở y tế ngay."]},"12a3070f":{"noi_dau":["Thức ăn hay mắc kẽ răng, dùng tăm tre lại sợ hở chân răng","Chỉ nha khoa khó dùng, nhất là người niềng răng hay bọc sứ","Đánh răng kỹ mà miệng vẫn chưa thấy sạch hẳn"],"cong_dung":["Máy Evolution 10 mức áp lực, bình 650 ml, tay cầm xoay 360 độ có nút tắt mở","Máy Nano nhỏ gọn, 3 mức áp lực, bình khoảng 440 ml, hợp không gian nhỏ","Kèm 5 đầu tăm cho dùng thường, niềng răng, implant, túi nha chu","Có túi đựng đầu tăm và túi đựng máy Nano khi đi xa","Đạt chứng nhận an toàn, hiệu quả của Hiệp hội Nha khoa Hoa Kỳ (ADA)"],"lieu_dung":"Đổ nước ấm vào bình, chọn áp lực thấp khi mới dùng, cúi người vào bồn rửa, đặt đầu tăm vào miệng rồi mới bật máy và đi dọc viền nướu. Dùng xong đổ hết nước, lau khô.","luu_y":["Máy dùng điện 120V (Bắc Mỹ); ở Việt Nam điện 220V phải dùng bộ đổi nguồn phù hợp.","Không dùng máy gần bồn nước đầy nước, không để máy ướt khi cắm điện."]},"5baf73c8":{"noi_dau":["Con ho về đêm, cả nhà mất ngủ theo","Trở trời là người lớn trẻ nhỏ đều sổ mũi, ho khan","Muốn có món dầu bôi quen thuộc để sẵn trong nhà"],"cong_dung":["Giảm ho tạm thời do cảm lạnh thông thường","Giảm tạm thời đau nhức nhẹ ở cơ và khớp","Hơi ấm, mùi thơm dễ chịu kéo dài đến 8 giờ theo công bố của hãng"],"thanh_phan_chinh":"Camphor 4,8%, dầu khuynh diệp 1,2%, menthol 2,6%","lieu_dung":"Giảm ho: người lớn và trẻ từ 2 tuổi xoa một lớp dày lên ngực và cổ, mặc quần áo rộng, dùng tối đa 3 lần/ngày. Giảm đau cơ: bôi lên vùng đau không quá 3–4 lần/ngày. Trẻ dưới 2 tuổi: hỏi bác sĩ.","luu_y":["Chỉ dùng ngoài da: không bôi vào mũi, miệng, mắt, vết thương; không băng kín.","Dễ cháy: không hơ nóng, không cho vào lò vi sóng hoặc nước nóng.","Không dùng cho trẻ dưới 2 tuổi khi chưa hỏi bác sĩ; ngưng dùng nếu ho kéo dài trên 7 ngày hoặc kèm sốt."]},"c73d7209":{"noi_dau":["Vai gáy, thắt lưng nhức mỏi sau ngày dài làm việc","Dùng dầu xoa thì dính tay, ám mùi ra quần áo","Đau cơ, đau khớp làm khó ngủ mỗi tối"],"cong_dung":["Giảm tạm thời đau nhẹ ở cơ và khớp","Cảm giác lạnh làm dịu cơn đau, sau đó ấm giúp thư giãn","Dạng lăn khô nhanh, không dính tay"],"thanh_phan_chinh":"Menthol 16%","lieu_dung":"Người lớn và trẻ trên 12 tuổi: lăn một lớp mỏng lên vùng đau, xoa đến khi thấm, không quá 3–4 lần/ngày. Trẻ từ 12 tuổi trở xuống: hỏi bác sĩ.","luu_y":["Chỉ dùng ngoài da; rửa tay bằng xà phòng sau khi dùng, đóng chặt nắp.","Phụ nữ có thai hoặc cho con bú hỏi ý kiến chuyên gia y tế trước khi dùng.","Để xa tầm tay trẻ em; nếu lỡ nuốt phải đến cơ sở y tế ngay."]},"a2aec0c2":{"noi_dau":["Sáng ra hắt hơi liên tục, nước mũi chảy không ngừng","Mắt ngứa, chảy nước mỗi khi thời tiết thay đổi","Ngứa mũi, ngứa họng khiến làm việc không tập trung"],"cong_dung":["Giảm tạm thời hắt hơi, sổ mũi do dị ứng","Giảm ngứa mắt, chảy nước mắt","Giảm triệu chứng viêm mũi dị ứng theo mùa","Giảm ngứa mũi hoặc ngứa họng"],"thanh_phan_chinh":"Diphenhydramine HCl 25 mg/viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: 1–2 viên mỗi 4–6 giờ. Trẻ 6 đến dưới 12 tuổi: 1 viên mỗi 4–6 giờ. Không quá 6 lần dùng trong 24 giờ. Trẻ dưới 6 tuổi: không dùng.","luu_y":["Gây buồn ngủ rõ rệt: tránh rượu, không lái xe hay vận hành máy; không dùng chung sản phẩm khác có diphenhydramine, kể cả loại bôi da.","Người bị tăng nhãn áp, bệnh phổi mạn tính, khó tiểu do phì đại tuyến tiền liệt phải hỏi bác sĩ.","Có thể gây kích động ở trẻ em; phụ nữ có thai, cho con bú hỏi bác sĩ trước khi dùng."]},"f549f95b":{"noi_dau":["Da bắt đầu xỉn màu, kém đàn hồi sau tuổi 35","Đi nắng nhiều, lo da nhanh lão hóa","Muốn chăm sóc sức khỏe từ bên trong mà không biết chọn gì"],"cong_dung":["Bổ sung astaxanthin nguồn AstaReal, chất chống oxy hóa từ vi tảo","Hỗ trợ làn da khỏe mạnh theo công bố trên nhãn","Góp phần chống oxy hóa cho cơ thể","Hỗ trợ sức khỏe tim mạch"],"thanh_phan_chinh":"Astaxanthin 12 mg/viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn có chất béo để hấp thu tốt hơn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"4b5a6421":{"noi_dau":["Soi gương thấy làn da khô hơn, kém căng mịn so với vài năm trước","Nếp nhăn quanh mắt, khoé miệng hiện rõ hơn khi cười","Muốn bổ sung collagen nhưng ngại viên to, khó uống mỗi ngày"],"cong_dung":["Bổ sung peptide collagen hoạt tính Verisol, góp phần hỗ trợ làn da khoẻ","Hỗ trợ làm giảm sự xuất hiện và độ sâu của nếp nhăn","Dạng bột không mùi, dễ pha vào nước, cà phê hay sữa chua","Không chứa gluten, lactose và đường"],"thanh_phan_chinh":"Collagen thuỷ phân Verisol 2.500 mg/muỗng gạt (2,5 g)","lieu_dung":"Người lớn: mỗi ngày 1 muỗng gạt (2,5 g), khuấy tan với đồ uống không có ga hoặc rắc vào thức ăn như sữa chua.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng."]},"4cbbefc6":{"noi_dau":["Ngồi máy tính cả ngày, cổ vai gáy mỏi nhừ lúc tối về","Đi xa say xe, lúc nào cũng muốn có chai dầu trong túi","Mùi dầu gió nồng quá khiến cả nhà khó chịu"],"cong_dung":["Giảm tạm thời các cơn đau nhức nhẹ ở cơ và khớp","Tinh dầu bạc hà và nụ đinh hương cho cảm giác mát, thơm dễ chịu","Chai nhỏ gọn, tiện mang theo khi đi làm, đi xa"],"lieu_dung":"Người lớn và trẻ từ 2 tuổi: thoa lên vùng đau, không quá 3–4 lần mỗi ngày. Trẻ dưới 2 tuổi: hỏi ý kiến bác sĩ.","luu_y":["Chỉ dùng ngoài da; tránh mắt, niêm mạc, vết thương hở hoặc da bị tổn thương.","Không băng kín và không dùng cùng túi chườm nóng.","Ngưng dùng và hỏi bác sĩ nếu triệu chứng kéo dài quá 7 ngày."]},"b8aadd2e":{"noi_dau":["Sáng nào thức dậy cũng hắt hơi liên tục, sổ mũi không dứt","Giao mùa là mắt ngứa, chảy nước, làm việc chẳng tập trung","Cả nhà hay dị ứng, mua lẻ từng vỉ vừa tốn vừa bất tiện"],"cong_dung":["Giảm tạm thời triệu chứng viêm mũi dị ứng do phấn hoa, bụi, lông thú","Giảm hắt hơi, sổ mũi, ngứa mũi hoặc ngứa họng","Giảm ngứa mắt, chảy nước mắt do dị ứng","Tác dụng kéo dài 24 giờ, uống 1 lần mỗi ngày"],"thanh_phan_chinh":"Cetirizine hydrochloride 10 mg/viên","lieu_dung":"Người lớn và trẻ từ 6 tuổi: uống 1 viên 10 mg mỗi ngày một lần, không quá 1 viên trong 24 giờ. Trẻ dưới 6 tuổi và người từ 65 tuổi: hỏi ý kiến bác sĩ.","luu_y":["Có thể gây buồn ngủ; tránh rượu bia, thận trọng khi lái xe hoặc vận hành máy.","Người bệnh gan, thận hỏi bác sĩ trước khi dùng; không khuyến nghị dùng khi đang cho con bú.","Không dùng nếu từng dị ứng với cetirizine hoặc hydroxyzine."]},"4c00ab26":{"noi_dau":["Đứng lên ngồi xuống thấy đầu gối cứng, phải đợi một lúc mới đi được","Ngại uống nhiều viên bổ khớp to mỗi ngày","Muốn giữ khớp linh hoạt để còn đi bộ, chơi với con cháu"],"cong_dung":["Hỗ trợ sự thoải mái và linh hoạt của khớp","Kết hợp omega-3, axit hyaluronic (HA) và astaxanthin trong một viên","Viên nang mềm nhỏ, chỉ cần 1 viên mỗi ngày"],"thanh_phan_chinh":"Omega-3, axit hyaluronic (HA) và astaxanthin","lieu_dung":"Uống 1 viên nang mềm mỗi ngày.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc chống đông hoặc dị ứng hải sản nên hỏi bác sĩ trước khi dùng."]},"232360d6":{"noi_dau":["Con ăn ít, bữa nào cũng phải dỗ dành mới chịu ăn","Thấy con thấp nhỏ hơn bạn cùng lớp, mẹ không khỏi sốt ruột","Muốn bổ sung dinh dưỡng cho con mà con lại kén vị"],"cong_dung":["Bổ sung dinh dưỡng cân đối, hỗ trợ trẻ tăng trưởng","Cung cấp 6 g đạm cùng 23 vitamin và khoáng chất mỗi lần dùng","Hương vanilla dễ uống, pha nhanh với nước","Nguyên liệu không biến đổi gen (Non-GMO)"],"thanh_phan_chinh":"6 g đạm, 23 vitamin và khoáng chất mỗi lần dùng","lieu_dung":"Mỗi lần pha 5 muỗng gạt không nén (bằng muỗng kèm theo, khoảng 1/3 cốc bột) với 3/4 cốc nước (khoảng 180 ml), khuấy hoặc lắc đều. Mỗi hộp khoảng 8 lần dùng.","luu_y":["Không dùng cho trẻ mắc bệnh galactosemia.","Đậy kín nắp sau khi mở, bảo quản nơi khô mát."]},"f9420ca3":{"noi_dau":["Tóc mỏng, xẹp, buộc lên thấy lưa thưa thiếu sức sống","Gội xong tóc khô xơ, rối, chải là gãy rụng","Muốn tóc trông dày dặn hơn mà không phải làm hoá chất"],"cong_dung":["Biotin (vitamin B7), collagen và protein lúa mì thuỷ phân nuôi dưỡng sợi tóc","Giúp tóc trông dày, bồng và khoẻ hơn","Làm mềm, giảm rối, dễ chải sau khi gội"],"thanh_phan_chinh":"Biotin (vitamin B7), collagen, protein lúa mì thuỷ phân","lieu_dung":"Sau khi gội, thoa nhiều dầu xả từ thân tóc đến ngọn, để 3–5 phút rồi xả sạch với nước.","luu_y":["Tránh để dính vào mắt; nếu dính, rửa ngay bằng nước sạch."]},"51cc1db0":{"noi_dau":["Leo vài bậc cầu thang là đầu gối đã lên tiếng","Sáng dậy khớp cứng, phải vận động một lúc mới thấy dễ chịu","Bố mẹ lớn tuổi đi lại chậm, con cái thương mà chưa biết bổ sung gì"],"cong_dung":["Bổ sung glucosamine, chondroitin và MSM, hỗ trợ sức khoẻ khớp","Hỗ trợ khớp và cơ vận động linh hoạt","Bổ sung vitamin D3, góp phần hỗ trợ xương chắc khoẻ","Sản phẩm được kiểm định USP"],"thanh_phan_chinh":"Glucosamine 1.500 mg, Chondroitin 800 mg, MSM 750 mg, Vitamin D3 2.000 IU (50 mcg) mỗi khẩu phần","lieu_dung":"Uống 2 viên mỗi ngày cùng nước và bữa ăn.","luu_y":["Sản phẩm có nguồn gốc từ động vật có vỏ (tôm, cua); người dị ứng hải sản cần thận trọng.","Phụ nữ có thai, cho con bú, người dưới 18 tuổi hoặc đang dùng thuốc chống đông nên hỏi bác sĩ trước khi dùng."]},"3021f4c0":{"noi_dau":["Con đi học về mệt, cần ly nước vừa ngon vừa có chất","Sáng vội, bé lười ăn sáng, mẹ lo con thiếu năng lượng","Mua gói nhỏ nhanh hết, muốn hộp lớn dùng cho cả nhà"],"cong_dung":["Thức uống cacao lúa mạch, bổ sung năng lượng cho ngày dài","Có chứa đạm, 8 vitamin và khoáng chất","Chỉ số đường huyết thấp (Low GI) theo công bố trên hộp","Hộp 1 kg dùng được khoảng 50 lần"],"lieu_dung":"Mỗi lần pha khoảng 3 thìa cà phê đầy (20 g) với 200 ml sữa, uống nóng hoặc lạnh. Đậy kín nắp và bảo quản nơi khô mát sau khi mở.","luu_y":["Có chứa sữa và mạch nha lúa mạch (gluten); người dị ứng cần đọc kỹ thành phần trên hộp."]},"7b34e307":{"noi_dau":["Tuần nào cũng vài lần nóng rát sau xương ức, nhất là sau bữa tối","Đang ngủ thì ợ chua trào lên, mất giấc cả đêm","Uống thuốc trung hoà axit chỉ đỡ được một lúc rồi lại bị"],"cong_dung":["Dùng cho chứng ợ nóng thường xuyên (từ 2 ngày/tuần trở lên), theo chỉ định trên nhãn","Giảm tiết axit dạ dày, tác dụng kéo dài 24 giờ","Có thể mất 1–4 ngày để đạt hiệu quả đầy đủ","Hộp gồm 3 liệu trình, mỗi liệu trình 14 ngày"],"thanh_phan_chinh":"Esomeprazole 20 mg/viên nang giải phóng chậm","lieu_dung":"Người từ 18 tuổi: uống 1 viên mỗi ngày với 1 cốc nước vào buổi sáng trước khi ăn, liên tục 14 ngày; nuốt nguyên viên, không nhai, không nghiền, không quá 1 viên/ngày. Không dùng quá 14 ngày hoặc quá 1 liệu trình mỗi 4 tháng nếu không có chỉ định của bác sĩ.","luu_y":["Không dùng cho người dưới 18 tuổi trừ khi bác sĩ chỉ định; không dùng nếu dị ứng esomeprazole.","Không dùng nếu khó nuốt, nôn ra máu hoặc đi ngoài phân đen – cần đi khám ngay.","Hỏi bác sĩ hoặc dược sĩ nếu đang dùng warfarin, clopidogrel, methotrexate hoặc thuốc kháng virus kê đơn."]},"b43369de":{"noi_dau":["Ho khan về đêm, cả nhà mất ngủ theo","Con ho liên tục, uống thuốc vài tiếng lại phải uống tiếp","Đi làm cứ ho mãi, ngại người xung quanh"],"cong_dung":["Giảm ho tạm thời do kích ứng họng và phế quản khi cảm lạnh","Giảm phản xạ ho, tác dụng kéo dài đến 12 giờ","Vị cam dễ uống, không đường sulfite, không cồn"],"thanh_phan_chinh":"Dextromethorphan polistirex, tương đương 30 mg dextromethorphan hydrobromide/5 ml","lieu_dung":"Lắc kỹ, đong bằng cốc kèm theo. Người lớn và trẻ từ 12 tuổi: 10 ml mỗi 12 giờ, không quá 20 ml/24 giờ; trẻ 6 đến dưới 12 tuổi: 5 ml mỗi 12 giờ, không quá 10 ml/24 giờ; trẻ 4 đến dưới 6 tuổi: 2,5 ml mỗi 12 giờ, không quá 5 ml/24 giờ; trẻ dưới 4 tuổi: không dùng.","luu_y":["Không dùng nếu đang dùng thuốc ức chế MAO hoặc mới ngưng trong vòng 2 tuần.","Hỏi bác sĩ nếu ho kéo dài do hút thuốc, hen, khí phế thũng hoặc ho có nhiều đờm.","Ngưng dùng và đi khám nếu ho quá 7 ngày, tái phát, hoặc kèm sốt, phát ban, đau đầu dai dẳng."]},"833bf638":{"noi_dau":["Đau đầu, đau răng ập đến lúc nửa đêm mà nhà không có thuốc","Đến kỳ đau bụng âm ỉ, làm gì cũng không tập trung","Con người lớn sốt, cảm cúm, muốn có sẵn thuốc trong tủ"],"cong_dung":["Giảm tạm thời đau đầu, đau răng, đau lưng, đau cơ","Giảm đau bụng kinh và đau nhức do cảm lạnh thông thường","Giảm đau nhẹ do viêm khớp","Hạ sốt tạm thời"],"thanh_phan_chinh":"Ibuprofen 200 mg/viên (thuốc giảm đau chống viêm không steroid – NSAID)","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi 4–6 giờ khi còn triệu chứng; nếu không đỡ có thể uống 2 viên; không quá 6 viên trong 24 giờ trừ khi bác sĩ chỉ định. Uống cùng thức ăn hoặc sữa nếu bị khó chịu dạ dày. Trẻ dưới 12 tuổi: hỏi ý kiến bác sĩ.","luu_y":["Nguy cơ xuất huyết dạ dày cao hơn ở người từ 60 tuổi, có tiền sử loét dạ dày, dùng thuốc chống đông, corticoid hoặc uống từ 3 ly rượu/ngày.","Thuốc NSAID có thể làm tăng nguy cơ đau tim, đột quỵ; không dùng ngay trước hoặc sau phẫu thuật tim.","Phụ nữ có thai từ tuần 20 trở đi không dùng trừ khi bác sĩ chỉ định; không dùng nếu từng dị ứng với thuốc giảm đau hạ sốt."]},"ead776ad":{"noi_dau":["Hắt hơi, sổ mũi kéo dài cả mùa, làm việc gì cũng dở dang","Dị ứng làm ngứa mũi, ngứa họng, đêm ngủ không yên","Mắt ngứa đỏ, chảy nước mỗi khi tiếp xúc bụi hay phấn hoa"],"cong_dung":["Giảm tạm thời triệu chứng viêm mũi dị ứng và dị ứng đường hô hấp trên","Giảm hắt hơi, sổ mũi, ngứa mũi hoặc ngứa họng","Giảm ngứa mắt, chảy nước mắt","Tác dụng kéo dài 24 giờ, uống 1 lần mỗi ngày"],"thanh_phan_chinh":"Levocetirizine dihydrochloride 5 mg/viên","lieu_dung":"Người 12–64 tuổi: uống 1 viên (5 mg) mỗi ngày vào buổi tối, không quá 1 viên/24 giờ; triệu chứng nhẹ có thể dùng 1/2 viên. Trẻ 6–11 tuổi: 1/2 viên (2,5 mg) vào buổi tối, không quá 1/2 viên/24 giờ. Trẻ dưới 6 tuổi và người từ 65 tuổi: hỏi ý kiến bác sĩ.","luu_y":["Không dùng nếu từng dị ứng với levocetirizine hoặc cetirizine, hoặc bị bệnh thận giai đoạn cuối.","Có thể gây buồn ngủ; tránh rượu bia, thận trọng khi lái xe; không khuyến nghị dùng khi cho con bú."]},"119811a1":{"noi_dau":["Sống giữa khói bụi thành phố, lúc nào cũng lo cho lá phổi","Hay đun nấu trong bếp, ngửi khói dầu mỡ mỗi ngày","Muốn chăm sóc hệ hô hấp cho cả nhà bằng thực phẩm tự nhiên"],"cong_dung":["Hỗ trợ sức khoẻ phổi theo công bố trên nhãn","Bổ sung chiết xuất bông cải xanh giàu sulforaphane glucosinolate (SGS)","Thuộc nhóm hỗ trợ tiêu hoá và thải độc của hãng"],"thanh_phan_chinh":"Chiết xuất bông cải xanh; 2 viên chứa lượng SGS tương đương 120 g bông cải xanh tươi","lieu_dung":"Người lớn: uống 2 viên mỗi ngày, hoặc theo hướng dẫn của nhân viên y tế.","luu_y":["Nếu triệu chứng kéo dài, hãy hỏi ý kiến nhân viên y tế."]},"ec760c3e":{"noi_dau":["Phòng đóng điều hoà cả ngày, mở cửa ra vẫn thấy mùi bí","Xịt phòng thơm được một lúc rồi bay hết","Muốn nhà lúc nào cũng thơm nhẹ khi khách đến chơi"],"cong_dung":["Lõi tinh dầu thay thế cho máy khuếch tán cắm điện Wallflowers","Toả hương liên tục, giữ phòng thơm nhẹ nhàng","Nhiều mùi để chọn: tươi mát, ngọt ngào, hương gỗ, hương hoa","Thay lõi nhanh, không cần đốt nến hay xịt"],"lieu_dung":"Vặn lõi vào máy Wallflowers, cắm máy vào ổ điện, để thẳng đứng. Thay lõi mới khi tinh dầu cạn.","luu_y":["Gây kích ứng mắt; đọc kỹ hướng dẫn in trên nhãn trước khi dùng.","Máy cắm Wallflowers dùng điện 110V và phích Mỹ, cần bộ đổi nguồn khi dùng tại Việt Nam.","Để xa tầm tay trẻ em và thú cưng."]},"1a18caa4":{"noi_dau":["Biết phải uống đủ nước nhưng nước lọc nhạt quá, uống không nổi","Ngâm trái cây trong bình, rót ra lại lẫn hạt lẫn xác","Cả nhà mỗi người một chai, tủ lạnh lúc nào cũng chật"],"cong_dung":["Ống lọc ở giữa để ngâm trái cây, thảo mộc, rót nước không lẫn xác","Dung tích lớn 2,13 lít, đủ cho cả nhà dùng trong ngày","Chất liệu nhựa không chứa BPA","Tay cầm chắc chắn, dễ rót"],"lieu_dung":"Cho trái cây cắt lát vào ống lọc, đổ nước và để tủ lạnh vài giờ cho ngấm vị. Rửa bình và ống lọc sau mỗi lần dùng; xem hướng dẫn trên bao bì về việc dùng máy rửa bát.","luu_y":[]},"ec2e1cd7":{"noi_dau":["Ăn xong hay đầy bụng, chướng hơi, khó chịu cả buổi","Đi ngoài thất thường, lúc táo lúc lỏng","Dùng kháng sinh xong thấy bụng dạ yếu hẳn đi"],"cong_dung":["Bổ sung 10 tỷ lợi khuẩn sống từ 12 chủng men vi sinh","Có thêm chất xơ prebiotic nuôi dưỡng lợi khuẩn","Hỗ trợ hệ tiêu hoá khoẻ mạnh","Góp phần hỗ trợ hệ miễn dịch; sản phẩm được kiểm định USP"],"thanh_phan_chinh":"10 tỷ lợi khuẩn sống (CFU), 12 chủng men vi sinh kèm prebiotic/viên","lieu_dung":"Uống 1 viên mỗi ngày.","luu_y":["Phụ nữ có thai, cho con bú, người có bệnh lý hoặc suy giảm miễn dịch nên hỏi bác sĩ trước khi dùng."]},"66c16449":{"noi_dau":["Mặt chăm kỹ mà cổ lại lộ nếp nhăn ngang, nhìn là biết tuổi","Da cổ và vùng ngực chảy xệ, mỏng như giấy nhăn","Mặc áo cổ rộng thấy tự ti vì vùng da trước ngực sạm màu"],"cong_dung":["Dưỡng săn chắc, giúp da vùng cổ và ngực trông căng mịn hơn","Giúp làm mờ nếp nhăn ngang ở cổ","Hỗ trợ cải thiện tình trạng da ngực nhăn nheo và không đều màu","Công nghệ NIA-114 độc quyền của hãng"],"thanh_phan_chinh":"Công nghệ NIA-114 (dẫn xuất niacin)","lieu_dung":"Sáng và tối, thoa lên vùng cổ và ngực đã làm sạch, massage theo chiều từ dưới lên.","luu_y":["Chỉ dùng ngoài da, tránh vùng mắt; ngưng dùng nếu da kích ứng."]},"22fa5c3b":{"noi_dau":["Áo trắng của con lâu ngày ố vàng, vết bẩn cổ áo giặt mãi không sạch","Đong nước giặt mỗi lần một kiểu, lúc thừa lúc thiếu","Đồ ăn, bùn đất dính quần áo phải vò tay rất mệt"],"cong_dung":["Viên giặt 3 trong 1 định lượng sẵn, không cần đong","Có chất xử lý vết bẩn tích hợp cùng Ultra Oxi làm sạch sâu","Dùng được cho mọi loại máy giặt, kể cả máy HE","Hộp lớn 104 viên dùng được lâu"],"lieu_dung":"Dùng tay khô lấy viên giặt, cho vào lồng giặt trước khi cho quần áo vào; không cho vào ngăn chứa bột giặt. Đậy kín nắp hộp sau khi lấy.","luu_y":["Nguy hiểm nếu cho vào miệng hoặc nuốt phải; để xa tầm tay trẻ em.","Gây kích ứng mắt; nếu dính vào mắt, rửa kỹ bằng nước sạch.","Không cắt, chọc thủng hay bóp vỡ viên giặt."]},"e3dc6da9":{"noi_dau":["Lỗ chân lông to, da đổ dầu, trang điểm nhanh xuống tông","Da xỉn màu, sần sùi dù đã rửa mặt kỹ","Bận rộn, không có thời gian cho quy trình dưỡng da nhiều bước"],"cong_dung":["Kết hợp AHA và BHA giúp tẩy tế bào chết nhẹ nhàng","Làm thông thoáng và giúp se khít lỗ chân lông","Giúp da sáng và săn chắc hơn","Bổ sung probiotic vi bao, hỗ trợ cân bằng hệ vi sinh trên da"],"thanh_phan_chinh":"AHA, BHA và probiotic vi bao","lieu_dung":"Sau khi rửa mặt, lau nhẹ một miếng pad khắp mặt, tránh vùng mắt; không cần rửa lại. Nên bắt đầu dùng cách ngày để da làm quen.","luu_y":["Sản phẩm có AHA có thể làm da nhạy cảm hơn với ánh nắng; dùng kem chống nắng hằng ngày.","Tránh vùng mắt; ngưng dùng nếu da kích ứng."]},"e678f522":{"noi_dau":["Đầu bàn chải dùng lâu bị xoè lông, đánh răng không còn sạch","Uống cà phê, trà mỗi ngày, răng dần ố vàng","Mua đầu thay lẻ vừa đắt vừa khó tìm hàng chuẩn"],"cong_dung":["Lông bàn chải trung tâm giúp loại bỏ vết ố, làm trắng răng","Kích cỡ đầy đủ, độ cứng lông vừa (Medium)","Có công nghệ BrushSync nhắc thay đầu bàn chải trên máy tương thích","Lắp kiểu bấm (click-on) vừa các thân máy Sonicare cùng dòng"],"lieu_dung":"Ấn đầu bàn chải khít vào trục máy Sonicare loại lắp bấm. Rửa sạch đầu bàn chải sau mỗi lần dùng, để khô; thay đầu mới khoảng 3 tháng một lần.","luu_y":["Không dùng cho máy Sonicare loại vặn ren (Essence) hoặc dòng PowerUp chạy pin."]},"5a9da0fb":{"noi_dau":["Đau đầu, nhức thái dương giữa giờ làm","Dùng dầu gió đổ ra tay dễ dây ra áo, ra túi","Mỏi vai gáy mà không muốn mùi dầu nồng ám người"],"cong_dung":["Giảm tạm thời các cơn đau nhức nhẹ ở cơ và khớp","Đầu lăn tiện lợi, thoa đúng chỗ, không dây ra tay","Hương oải hương và khuynh diệp dịu nhẹ, dễ chịu","Chai 8 ml nhỏ gọn, bỏ túi mang theo"],"lieu_dung":"Người lớn và trẻ từ 2 tuổi: lăn lên vùng đau, không quá 3–4 lần mỗi ngày. Trẻ dưới 2 tuổi: hỏi ý kiến bác sĩ.","luu_y":["Chỉ dùng ngoài da; tránh mắt, niêm mạc và vùng da bị tổn thương.","Không băng kín; ngưng dùng và hỏi bác sĩ nếu triệu chứng kéo dài quá 7 ngày."]},"b9f85209":{"noi_dau":["Tuần nào cũng vài bữa nóng rát vùng ngực sau khi ăn","Nằm xuống là ợ chua, cổ họng đắng chát","Phải kiêng đủ món mà chứng ợ nóng vẫn quay lại"],"cong_dung":["Dùng cho chứng ợ nóng thường xuyên (từ 2 ngày/tuần trở lên), theo chỉ định trên nhãn","Giảm tiết axit dạ dày, tác dụng kéo dài 24 giờ","Có thể mất 1–4 ngày để đạt hiệu quả đầy đủ","Hộp gồm 3 liệu trình 14 ngày, không chứa natri"],"thanh_phan_chinh":"Lansoprazole 15 mg/viên nang giải phóng chậm","lieu_dung":"Người từ 18 tuổi: uống 1 viên mỗi ngày với 1 cốc nước vào buổi sáng trước khi ăn, liên tục 14 ngày; nuốt nguyên viên, không nhai, không nghiền, không quá 1 viên/ngày. Không dùng quá 14 ngày hoặc quá 1 liệu trình mỗi 4 tháng nếu không có chỉ định của bác sĩ.","luu_y":["Không dùng cho người dưới 18 tuổi trừ khi bác sĩ chỉ định; không dùng nếu dị ứng lansoprazole.","Không dùng nếu khó nuốt, nôn ra máu hoặc đi ngoài phân đen – cần đi khám ngay.","Hỏi bác sĩ hoặc dược sĩ nếu đang dùng warfarin, digoxin, tacrolimus, theophylline hoặc thuốc kháng nấm, kháng virus kê đơn."]},"ef1f1959":{"noi_dau":["Da khô, kém đàn hồi, trang điểm không còn mịn như trước","Tóc mỏng, móng tay dễ gãy, chăm ngoài mãi không thấy khác","Ngại nuốt viên uống, muốn bổ sung bằng dạng nước cho dễ"],"cong_dung":["Bổ sung collagen kết hợp biotin, hỗ trợ làn da tươi sáng","Hỗ trợ làm giảm sự xuất hiện và độ sâu của nếp nhăn","Dạng nước vị dâu rừng dễ uống, không đường","Không chứa gluten, không biến đổi gen (Non-GMO)"],"thanh_phan_chinh":"Collagen và biotin (chưa xác định được hàm lượng)","lieu_dung":"Lắc đều trước khi dùng, uống 1 lần mỗi ngày theo muỗng đong in trên nhãn (chai 900 ml đủ 90 lần dùng). Bảo quản trong tủ lạnh sau khi mở nắp.","luu_y":["Phụ nữ có thai, cho con bú hoặc đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng."]},"d96fff5c":{"noi_dau":["Sắp đến dịp lễ mà chưa nghĩ ra món quà vừa sang vừa dùng được","Tặng quà cho sếp, đồng nghiệp sợ không đúng gu","Muốn một món quà có sẵn hộp đẹp, không phải gói thêm"],"cong_dung":["Ly giữ nhiệt Starbucks chính hãng, có logo nàng tiên cá dập nổi","Kèm gói cacao Classic Hot Cocoa hoặc cà phê xay Caffè Verona cùng bánh","Hộp quà trong suốt, đẹp sẵn để tặng","Hai mẫu màu xanh đậm và vàng ánh kim"],"lieu_dung":"Rửa ly bằng tay với nước ấm và xà phòng trước khi dùng lần đầu. Đồ ăn, thức uống kèm theo cần xem hạn sử dụng in trên gói.","luu_y":["Ly giữ nhiệt bằng kim loại, không cho vào lò vi sóng."]}};
